#[test]
fn information_register_master_dimension_scan_keeps_only_a_proven_prefix() {
    let complete = vec![
        Some(("First".to_string(), true)),
        Some(("Ordinary".to_string(), false)),
        Some(("Second".to_string(), true)),
    ];
    assert_eq!(
        information_register_known_master_dimension_prefix(&complete, 3, 3),
        Some(vec!["First".to_string(), "Second".to_string()])
    );
    assert_eq!(
        information_register_known_master_dimension_prefix(&[], 0, 0),
        Some(Vec::new()),
        "a completely decoded empty declaration is evidence"
    );

    let late_refusal = vec![
        Some(("First".to_string(), true)),
        Some(("Ordinary".to_string(), false)),
        None,
        Some(("UnprovenLater".to_string(), true)),
    ];
    assert_eq!(
        information_register_known_master_dimension_prefix(&late_refusal, 4, 3),
        Some(vec!["First".to_string()]),
        "only master positions before the first refusal are stable"
    );

    let early_refusal = vec![
        Some(("Ordinary".to_string(), false)),
        None,
        Some(("UnprovenLater".to_string(), true)),
    ];
    assert_eq!(
        information_register_known_master_dimension_prefix(&early_refusal, 3, 2),
        None,
        "an empty partial prefix must not be mistaken for no master dimensions"
    );
    assert_eq!(
        information_register_known_master_dimension_prefix(&complete, 4, 3),
        None,
        "a declaration-count mismatch proves no positional prefix"
    );
}

#[test]
fn form_navigation_panel_preserves_raw_item_order_and_rejects_bad_counts() {
    let register_uuid = "88888888-8888-4888-8888-888888888888";
    let command_uuid = "99999999-9999-4999-8999-999999999999";
    let item_tail = r#",{0},0,{0},0,0,{0,{0,{"B",0},0}}"#;
    let body = deflate_for_test(
        format!(
            r#"{{4,{{59,0,0,0,0,1,0,0,00000000-0000-0000-0000-000000000000,1}},"",{{0}},{{0,0}},{{0,0}},{{0,3,{{3,0,{{1,{register_uuid}}}{item_tail}}},{{3,1,{{0,71e0226e-ebb2-4e33-8745-0a94a01bbf15}}{item_tail}}},{{3,2,{{0,{command_uuid}}}{item_tail}}}}},{{0,0}},0,0}}"#
        )
        .as_bytes(),
    );
    let object_refs = BTreeMap::from([
        (
            register_uuid.to_string(),
            "AccumulationRegister.Stock".to_string(),
        ),
        (
            command_uuid.to_string(),
            "CommonCommand.Attachments".to_string(),
        ),
    ]);
    let xml = extract_form_body_xml(&body, &object_refs).unwrap();
    let recorder = xml
        .find("AccumulationRegister.Stock.StandardCommand.OpenByRecorder")
        .unwrap();
    let restore = xml.find("Form.StandardCommand.RestoreValues").unwrap();
    let attachments = xml.find("CommonCommand.Attachments").unwrap();
    assert!(recorder < restore && restore < attachments);

    let malformed = vec![
        "{0}".to_string(),
        "{0,0}".to_string(),
        "{0,0}".to_string(),
        format!(
            r#"{{0,2,{{3,0,{{0,{command_uuid}}},{{0}},0,{{0}},0,0,{{0,{{0,{{"B",0}},0}}}}}}}}"#
        ),
    ];
    assert!(extract_form_command_interface(&malformed, &object_refs).is_none());
}

/// The owners of a named type set are derived from the leaves the set declares,
/// not stored beside them: one table answers both this route and the
/// `<FillValue>` writer.
#[test]
fn information_register_type_set_uses_defined_type_owner_index() {
    let value_types = [ConstantValueType::ReferenceTypeSet {
        reference: "cfg:DefinedType.ProductOwner".to_string(),
    }];
    let type_set_leaves = BTreeMap::from([(
        "cfg:DefinedType.ProductOwner".to_string(),
        vec![ConstantValueType::Reference {
            reference: "cfg:CatalogRef.Products".to_string(),
        }],
    )]);

    assert_eq!(
        information_register_value_owner_references(&value_types, &type_set_leaves),
        BTreeSet::from(["Catalog.Products".to_string()])
    );
    assert!(information_register_value_owner_references(&value_types, &BTreeMap::new()).is_empty());
}

