#[test]
fn converts_binary_rows_to_config_rows_with_lowercase_hex() {
    let rows = config_rows_from_binary(vec![
        BinaryConfigRow {
            file_name: "first".to_string(),
            part_no: 0,
            data_size: 2,
            binary: vec![0xaa, 0xbb],
        },
        BinaryConfigRow {
            file_name: "second".to_string(),
            part_no: 0,
            data_size: 1,
            binary: vec![0xcc],
        },
    ]);

    assert_eq!(rows.len(), 2);
    assert_eq!(rows[0].file_name, "first");
    assert_eq!(rows[0].binary_hex, "aabb");
    assert_eq!(rows[1].file_name, "second");
    assert_eq!(rows[1].binary_hex, "cc");
}

#[test]
fn timing_report_add_assign_keeps_sqlcmd_bcp_breakdown() {
    let mut total = MssqlDumpTimingReport {
        fetch_headers_ms: 10,
        fetch_headers_sqlcmd_ms: 10,
        prepare_metadata_fetch_ms: 20,
        prepare_metadata_fetch_sqlcmd_ms: 3,
        prepare_metadata_fetch_bcp_ms: 17,
        fetch_rows_ms: 30,
        fetch_rows_bcp_ms: 30,
        fetch_row_batches: 2,
        fetch_row_batch_max_rows: 5,
        fetch_row_batch_max_binary_bytes: 100,
        ..MssqlDumpTimingReport::default()
    };
    let next = MssqlDumpTimingReport {
        fetch_headers_ms: 1,
        fetch_headers_sqlcmd_ms: 1,
        prepare_metadata_fetch_ms: 2,
        prepare_metadata_fetch_sqlcmd_ms: 0,
        prepare_metadata_fetch_bcp_ms: 2,
        fetch_rows_ms: 3,
        fetch_rows_bcp_ms: 3,
        fetch_row_batches: 1,
        fetch_row_batch_max_rows: 9,
        fetch_row_batch_max_binary_bytes: 50,
        ..MssqlDumpTimingReport::default()
    };

    total.add_assign(&next);

    assert_eq!(total.fetch_headers_ms, 11);
    assert_eq!(total.fetch_headers_sqlcmd_ms, 11);
    assert_eq!(total.prepare_metadata_fetch_ms, 22);
    assert_eq!(total.prepare_metadata_fetch_sqlcmd_ms, 3);
    assert_eq!(total.prepare_metadata_fetch_bcp_ms, 19);
    assert_eq!(total.fetch_rows_ms, 33);
    assert_eq!(total.fetch_rows_bcp_ms, 33);
    assert_eq!(total.fetch_row_batches, 3);
    assert_eq!(total.fetch_row_batch_max_rows, 9);
    assert_eq!(total.fetch_row_batch_max_binary_bytes, 100);
}

#[test]
fn dump_timing_summary_extracts_batch_followup_fields() {
    let half_gib = 512 * 1024 * 1024usize;
    let report = MssqlDumpConfigReport {
        database: "PerfDb".to_string(),
        output_dir: PathBuf::from(r"E:\ibcmd_lab\perf\full"),
        tables: vec![MssqlDumpedTableReport {
            table: "Config".to_string(),
            rows: 12,
            binary_bytes: half_gib,
            inflated_rows: 0,
            module_text_rows: 0,
            metadata_xml_rows: 0,
            source_asset_rows: 8,
            source_assets: SourceAssetCompletenessReport::default(),
            metadata_root_inventory: RootMetadataInventoryReport {
                scope: RootMetadataInventoryScope::Scoped,
                candidate_set_complete: true,
                expected: 0,
                emitted: 0,
                missing: 0,
                misses_by_reason: BTreeMap::new(),
                entries: Vec::new(),
            },
            timings: MssqlDumpTimingReport {
                prepare_indexes_ms: 40,
                prepare_metadata_fetch_ms: 11,
                prepare_metadata_texts_ms: 12,
                prepare_reference_indexes_ms: 13,
                prepare_command_refs_ms: 14,
                fetch_rows_ms: 1000,
                fetch_rows_bcp_ms: 900,
                fetch_row_batches: 2,
                fetch_row_batch_max_rows: 7,
                fetch_row_batch_max_binary_bytes: 300 * 1024 * 1024,
                process_rows_wall_ms: 2000,
                source_asset_cpu_ms: 123,
                source_asset_form_cpu_ms: 80,
                source_asset_inflated_cpu_ms: 30,
                source_asset_help_cpu_ms: 13,
                source_asset_form_xml_cpu_ms: 70,
                source_asset_form_child_items_cpu_ms: 50,
                source_asset_form_properties_cpu_ms: 10,
                ..MssqlDumpTimingReport::default()
            },
        }],
        total_rows: 12,
        total_binary_bytes: half_gib,
        total_inflated_rows: 0,
        total_module_text_rows: 0,
        total_metadata_xml_rows: 0,
        total_source_asset_rows: 8,
        source_assets: SourceAssetCompletenessReport::default(),
        timings: MssqlDumpTimingReport {
            prepare_indexes_ms: 40,
            prepare_metadata_fetch_ms: 11,
            prepare_metadata_fetch_bcp_ms: 11,
            prepare_metadata_texts_ms: 12,
            prepare_reference_indexes_ms: 13,
            prepare_command_refs_ms: 14,
            fetch_rows_ms: 1000,
            fetch_rows_bcp_ms: 900,
            fetch_row_batches: 2,
            fetch_row_batch_max_rows: 7,
            fetch_row_batch_max_binary_bytes: 300 * 1024 * 1024,
            process_rows_wall_ms: 2000,
            source_asset_cpu_ms: 123,
            source_asset_form_cpu_ms: 80,
            source_asset_inflated_cpu_ms: 30,
            source_asset_help_cpu_ms: 13,
            source_asset_form_xml_cpu_ms: 70,
            source_asset_form_child_items_cpu_ms: 50,
            source_asset_form_properties_cpu_ms: 10,
            ..MssqlDumpTimingReport::default()
        },
        incremental: None,
    };
    let json = serde_json::to_string(&report).unwrap();

    let summary = parse_dump_timing_summary(&json, Some(PathBuf::from("report.json"))).unwrap();

    assert_eq!(summary.report_path, Some(PathBuf::from("report.json")));
    assert_eq!(summary.database, "PerfDb");
    assert_eq!(summary.batch_cap_binary_bytes, 256 * 1024 * 1024);
    assert_eq!(summary.fetch_row_batches, 2);
    assert_eq!(summary.fetch_row_batch_max_rows, 7);
    assert_eq!(summary.fetch_row_batch_max_binary_mib, 300);
    assert_eq!(summary.fetch_rows_ms_per_gib, Some(2000));
    assert_eq!(summary.process_rows_wall_ms_per_gib, Some(4000));
    assert_eq!(summary.source_asset_cpu_ms, 123);
    assert_eq!(summary.source_asset_cpu_ms_per_row, Some(15));
    assert_eq!(summary.source_asset_cpu_breakdown[0].metric, "form");
    assert_eq!(summary.source_asset_cpu_breakdown[0].cpu_ms, 80);
    assert_eq!(summary.source_asset_cpu_breakdown[1].metric, "inflated");
    assert_eq!(summary.form_cpu_breakdown[0].metric, "form_xml");
    assert_eq!(summary.form_cpu_breakdown[1].metric, "child_items");
    assert_eq!(summary.tables[0].table, "Config");
    assert_eq!(summary.tables[0].fetch_row_batch_max_binary_mib, 300);
    assert_eq!(summary.tables[0].source_asset_cpu_ms_per_row, Some(15));
}

#[test]
fn source_asset_completeness_report_is_deterministic_and_strict() {
    let unknown = SourceAssetCompletenessReport::default();
    assert_eq!(unknown.status, SourceAssetCompletenessStatus::Unknown);
    assert!(!unknown.candidate_set_complete);

    let mut complete = SourceAssetCompletenessReport::default();
    complete.record_emitted();
    complete.finish_inventory(SourceAssetCompletenessScope::Full, true, 1);
    assert_eq!(complete.status, SourceAssetCompletenessStatus::Complete);
    assert_eq!(
        complete.expected,
        complete.emitted + complete.opaque + complete.missing
    );
    complete.ensure_complete(true).unwrap();

    let mut report = SourceAssetCompletenessReport::default();
    report.record_emitted();
    let mut opaque_entries = Vec::new();
    for (path, item_id, raw_sha256) in [
        ("Forms/Z/Ext/Form.xml", "20", "b"),
        ("Forms/A/Ext/Form.xml", "10", "a"),
    ] {
        opaque_entries.push(SourceAssetCompletenessEntry {
            family: "form".to_string(),
            code: "source_asset.form.choice_parameters.opaque_omitted".to_string(),
            classification: "opaque_property_omitted".to_string(),
            parse_error_class: None,
            table: "Config".to_string(),
            source_row_id: format!("row-{item_id}"),
            asset_path: path.to_string(),
            form_owner_reference: None,
            form_item_id: item_id.to_string(),
            form_item_tag: "InputField".to_string(),
            property: "ChoiceParameters".to_string(),
            property_profile: "input_field_extended_options".to_string(),
            property_slot: 58,
            raw_length: 17,
            raw_sha256: raw_sha256.repeat(64),
        });
    }
    report.record_opaque(opaque_entries);
    report.finish_inventory(SourceAssetCompletenessScope::Full, true, 2);

    assert_eq!(report.status, SourceAssetCompletenessStatus::Partial);
    assert_eq!(report.emitted, 1);
    assert_eq!(report.opaque, 1);
    assert_eq!(report.opaque_property_count, 2);
    assert_eq!(report.expected, 2);
    assert_eq!(report.missing, 0);
    assert_eq!(
        report
            .reasons
            .get("source_asset.form.choice_parameters.opaque_omitted"),
        Some(&2)
    );
    assert_eq!(report.affected_assets[0].asset_path, "Forms/A/Ext/Form.xml");
    assert!(report.ensure_complete(true).is_err());

    let json = serde_json::to_string(&report).unwrap();
    assert!(!json.contains("unsupported-choice-parameters"));
}

#[test]
fn source_asset_discovery_fails_closed_for_recognized_family_decoder_misses() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-source-completeness-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    let _scratch = crate::test_scratch::TestScratch::adopt(&root);
    fs::create_dir_all(&root).unwrap();
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let role_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let subsystem_uuid = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let catalog_metadata = deflate_for_test(
        format!(
            "{{1,{{57,{{0,{{3,{{1,0,{catalog_uuid}}},\"Products\",{{1,\"en\",\"Products\"}},\"\"}}}}}}}}"
        )
        .as_bytes(),
    );
    let role_metadata = deflate_for_test(
        format!("{{1,{{6,{{3,{{1,0,{role_uuid}}},\"Editor\",{{1,\"en\",\"Editor\"}},\"\"}},0}}}}")
            .as_bytes(),
    );
    let subsystem_metadata = deflate_for_test(
        format!(
            "{{1,{{22,{{3,{{1,0,{subsystem_uuid}}},\"Admin\",{{1,\"en\",\"Admin\"}},\"\"}},1}}}}"
        )
        .as_bytes(),
    );
    let invalid = deflate_for_test(b"{invalid-source-asset}");
    let row = |file_name: String, bytes: &[u8]| ConfigRow {
        file_name,
        part_no: 0,
        data_size: bytes.len() as i64,
        binary_hex: encode_hex_for_test(bytes),
    };
    let rows = vec![
        row(catalog_uuid.to_string(), &catalog_metadata),
        row(format!("{catalog_uuid}.1"), &invalid),
        row(format!("{catalog_uuid}.1c"), &invalid),
        row(role_uuid.to_string(), &role_metadata),
        row(format!("{role_uuid}.0"), &invalid),
        row(subsystem_uuid.to_string(), &subsystem_metadata),
        row(format!("{subsystem_uuid}.1"), &invalid),
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert_eq!(
        dumped.source_assets.status,
        SourceAssetCompletenessStatus::Unknown
    );
    assert!(!dumped.source_assets.candidate_set_complete);
    for reason in [
        "source_asset.discovery.help_decoder_failed",
        "source_asset.discovery.predefined_data_decoder_failed",
        "source_asset.discovery.role_rights_decoder_failed",
        "source_asset.discovery.command_interface_decoder_failed",
    ] {
        assert_eq!(
            dumped.source_assets.reasons.get(reason),
            Some(&1),
            "{reason}"
        );
    }
    assert_eq!(dumped.source_assets.missing, 4);
    assert_eq!(
        dumped.source_assets.expected,
        dumped.source_assets.emitted + dumped.source_assets.opaque + dumped.source_assets.missing
    );
    assert!(dumped.source_assets.ensure_complete(true).is_err());
}

