#[test]
fn owner_bound_source_assets_share_canonical_indexed_and_dynamic_routes() {
    use ibcmd_compiler_families::compiler::families::assets::{
        ConfigRowId, SourceAssetRegistry, SourceAssetRole,
    };

    let cases = [
        (
            "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
            "Role",
            "Editor",
            "Roles/Editor",
            ".0",
            SourceAssetRole::Rights,
            deflate_for_test(b"{10,{0},{0},0,1,0,4294967295}"),
        ),
        (
            "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
            "AccumulationRegister",
            "Stock",
            "AccumulationRegisters/Stock",
            ".3",
            SourceAssetRole::Aggregates,
            // One column-`#` (Id) plus two column-`N` (UseCode, Periodicity)
            // descriptors and a single data row: a genuinely non-empty
            // aggregate. A structurally-valid-but-zero-row blob (as this
            // fixture used to be) is exactly the shape the platform never
            // writes `Ext/Aggregates.xml` for -- see
            // `owner_bound_source_asset`'s `Aggregates` arm -- so it no
            // longer belongs in a fixture meant to prove an asset gets
            // created.
            deflate_for_test(
                b"{0,{9,{3,{0,\"Id\",{0,{\"#\"}}},{0,\"UseCode\",{0,{\"N\"}}},\
{0,\"Periodicity\",{0,{\"N\"}}}},{0,0,{0,1,{0,0,3,\
{0,{1,11111111-1111-4111-8111-111111111111}},{0,0},{0,1}}}}}}",
            ),
        ),
    ];

    for (uuid, family, name, object_path, suffix, role, bytes) in cases {
        let body_id = format!("{uuid}{suffix}");
        let reference = format!("{family}.{name}");
        let object_refs = BTreeMap::from([(uuid.to_owned(), reference.clone())]);
        let owner = BodyOwnerSourceReference {
            kind: family.to_owned(),
            canonical_name: name.to_owned(),
            object_path: PathBuf::from(object_path),
        };
        let row_id = ConfigRowId::parse(&body_id).unwrap();
        let dynamic = dynamic_owner_bound_source_asset(
            &row_id,
            &owner,
            Some(&reference),
            &bytes,
            &object_refs,
            &BTreeMap::new(),
        )
        .unwrap_or_else(|| panic!("valid unindexed {family} owner-bound relation"));

        let body_row = ConfigRow {
            file_name: body_id.clone(),
            part_no: 0,
            data_size: bytes.len() as i64,
            binary_hex: encode_hex_for_test(&bytes),
        };
        let metadata = MetadataTextRow {
            file_name: uuid.to_owned(),
            text: String::new(),
            object_code: Some(0),
            header: Some(MetadataHeader {
                uuid: uuid.to_owned(),
                name: name.to_owned(),
                synonyms: Vec::new(),
                comment: String::new(),
                template_type_code: None,
            }),
            kind: Some(family.to_owned()),
            folder: Some(match role {
                SourceAssetRole::Rights => "Roles",
                SourceAssetRole::Aggregates => "AccumulationRegisters",
                _ => unreachable!(),
            }),
        };
        let file_names = BTreeSet::from([body_id.as_str()]);
        let rows_by_file_name = BTreeMap::from([(body_id.as_str(), &body_row)]);
        let indexed = source_assets_from_metadata_text_inner(
            &metadata,
            &file_names,
            &rows_by_file_name,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &object_refs,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap();
        assert!(indexed.misses.is_empty());
        assert_eq!(indexed.assets.len(), 1);
        let (indexed_id, indexed) = &indexed.assets[0];
        assert_eq!(indexed_id, &body_id);
        assert_eq!(indexed.primary_path, dynamic.primary_path);
        assert_eq!(
            indexed.primary_path,
            PathBuf::from(object_path).join(
                SourceAssetRegistry
                    .route(family, role)
                    .unwrap()
                    .relative_path()
            )
        );
        match (&indexed.kind, &dynamic.kind, role) {
            (SourceAssetKind::RoleRights, SourceAssetKind::RoleRights, SourceAssetRole::Rights) => {
            }
            (
                SourceAssetKind::AccumulationRegisterAggregates {
                    register_name: indexed_name,
                },
                SourceAssetKind::AccumulationRegisterAggregates {
                    register_name: dynamic_name,
                },
                SourceAssetRole::Aggregates,
            ) => {
                assert_eq!(indexed_name, name);
                assert_eq!(dynamic_name, name);
            }
            _ => panic!("indexed and dynamic owner-bound assets differ"),
        }

        assert!(
            dynamic_owner_bound_source_asset(
                &row_id,
                &owner,
                Some(&format!("{family}.Other")),
                &bytes,
                &object_refs,
                &BTreeMap::new(),
            )
            .is_none(),
            "owner mismatch must fail closed"
        );
    }
}

#[test]
fn dump_timing_summary_defaults_missing_new_timing_fields() {
    let json = r#"{
            "database": "OldReport",
            "output_dir": "E:\\ibcmd_lab\\perf\\old",
            "tables": [{
                "table": "Config",
                "rows": 1,
                "binary_bytes": 0,
                "inflated_rows": 0,
                "module_text_rows": 0,
                "metadata_xml_rows": 0,
                "source_asset_rows": 0,
                "timings": {"fetch_rows_ms": 5}
            }],
            "total_rows": 1,
            "total_binary_bytes": 0,
            "total_inflated_rows": 0,
            "total_module_text_rows": 0,
            "total_metadata_xml_rows": 0,
            "total_source_asset_rows": 0,
            "timings": {"fetch_rows_ms": 5}
        }"#;

    let legacy_report: MssqlDumpConfigReport = serde_json::from_str(json).unwrap();
    assert_eq!(
        legacy_report.tables[0].metadata_root_inventory,
        RootMetadataInventoryReport::default()
    );
    let summary = parse_dump_timing_summary(json, None).unwrap();

    assert_eq!(summary.fetch_rows_ms, 5);
    assert_eq!(summary.fetch_row_batches, 0);
    assert_eq!(summary.fetch_row_batch_max_binary_bytes, 0);
    assert_eq!(summary.fetch_rows_ms_per_gib, None);
    assert_eq!(summary.source_asset_cpu_ms_per_row, None);
    assert!(summary.source_asset_cpu_breakdown.is_empty());
    assert!(summary.form_cpu_breakdown.is_empty());
}

#[test]
fn parses_native_bcp_rows_and_assembles_parts() {
    let mut bytes = Vec::new();
    push_native_bcp_row(&mut bytes, "first", 0, 5, b"abc");
    push_native_bcp_row(&mut bytes, "first", 1, 5, b"de");
    push_native_bcp_row(&mut bytes, "second", 0, 1, b"z");

    let parts = parse_bcp_native_config_rows(&bytes).unwrap();
    let rows = assemble_binary_config_rows(parts).unwrap();

    assert_eq!(rows.len(), 2);
    assert_eq!(rows[0].file_name, "first");
    assert_eq!(rows[0].part_no, 0);
    assert_eq!(rows[0].data_size, 5);
    assert_eq!(rows[0].binary, b"abcde");
    assert_eq!(rows[1].file_name, "second");
    assert_eq!(rows[1].binary, b"z");
}

