#[test]
fn parses_and_formats_metadata_child_fill_value_variants() {
    let object_refs = BTreeMap::from([(
        "3a87ef2a-9de1-4d34-9e5f-3c8cdf53b3ab".to_string(),
        "Catalog.Валюты.EmptyRef".to_string(),
    )]);

    let type_index = BTreeMap::new();
    let date_time = parse_metadata_child_fill_value(
        Some(r#"{"D",00010101000000}"#),
        &[],
        &type_index,
        &object_refs,
    )
    .unwrap();
    let decimal =
        parse_metadata_child_fill_value(Some(r#"{"N",0}"#), &[], &type_index, &object_refs)
            .unwrap();
    let design_time_ref = parse_metadata_child_fill_value(
            Some(
                r##"{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{0,3a87ef2a-9de1-4d34-9e5f-3c8cdf53b3ab,00000000-0000-0000-0000-000000000000}}"##,
            ),
            &[],
            &type_index,
            &object_refs,
        )
        .unwrap();
    let boolean_nil = parse_metadata_child_fill_value(
        Some(r#"{"U"}"#),
        &[ConstantValueType::Boolean],
        &type_index,
        &object_refs,
    )
    .unwrap();

    assert!(matches!(
        date_time,
        MetadataChildFillValue::DateTime(ref value) if value == "0001-01-01T00:00:00"
    ));
    assert!(matches!(
        decimal,
        MetadataChildFillValue::Decimal(ref value) if value == "0"
    ));
    assert!(matches!(
        design_time_ref,
        MetadataChildFillValue::DesignTimeRef(ref value) if value == "Catalog.Валюты.EmptyRef"
    ));
    assert!(matches!(boolean_nil, MetadataChildFillValue::Nil));
    assert_eq!(
        format_metadata_child_fill_value_xml(
            &MetadataChildFillValue::DateTime("0001-01-01T00:00:00".to_string()),
            &[],
            &MetadataTypeSetLeafIndex::new(),
        ),
        r#"<FillValue xsi:type="xs:dateTime">0001-01-01T00:00:00</FillValue>"#
    );
    assert_eq!(
        format_metadata_child_fill_value_xml(
            &MetadataChildFillValue::Decimal("0".to_string()),
            &[],
            &MetadataTypeSetLeafIndex::new(),
        ),
        r#"<FillValue xsi:type="xs:decimal">0</FillValue>"#
    );
    assert_eq!(
        format_metadata_child_fill_value_xml(
            &MetadataChildFillValue::DesignTimeRef("Catalog.Валюты.EmptyRef".to_string()),
            &[],
            &MetadataTypeSetLeafIndex::new(),
        ),
        r#"<FillValue xsi:type="xr:DesignTimeRef">Catalog.Валюты.EmptyRef</FillValue>"#
    );
}

/// The empty-string fill value is spelled by the attribute's declared type.
///
/// Evidence, ERP УХ 3.2.12.6, on the platform's own bytes:
/// `InformationRegisters/КлассыКонтрагентов` carries `{"S",""}` on
/// `ПроцентАванса` and `СрокОтсрочки`, both typed `{"Pattern",{"N",3,0,1}}`,
/// and the platform writes `<FillValue xsi:nil="true"/>`;
/// `DataProcessors/ФормированиеЗаказовПоставщикуПоПлану` carries the very same
/// `{"S",""}` on `Артикул`, typed `{"Pattern",{"#",055d69df-...}}` --
/// `DefinedType.Артикул`, a string -- and the platform writes
/// `<FillValue xsi:type="xs:string"/>`.
/// `DataProcessors/ОтменаИсполненияПлатежныхПозиций` carries it on `Сумма`,
/// typed the same way but naming `DefinedType.ДенежнаяСуммаЛюбогоЗнака`, a
/// number, and the platform writes the nil element. Nothing in the attribute's
/// own bytes tells the last two apart, so a type set the leaf index cannot
/// answer leaves the list undecided and the stored spelling stands.
#[test]
fn empty_string_fill_value_follows_the_declared_type() {
    let empty = MetadataChildFillValue::String(String::new());
    let string_type = [ConstantValueType::String {
        length: Some(50),
        allowed_length_flag: 1,
    }];
    let number_type = [ConstantValueType::Number {
        digits: 3,
        fraction_digits: 0,
        allowed_sign_flag: 1,
    }];
    let reference_type = [ConstantValueType::Reference {
        reference: "cfg:CatalogRef.Валюты".to_string(),
    }];
    let type_set = [ConstantValueType::ReferenceTypeSet {
        reference: "cfg:DefinedType.Артикул".to_string(),
    }];
    let mixed = [
        ConstantValueType::Number {
            digits: 3,
            fraction_digits: 0,
            allowed_sign_flag: 1,
        },
        ConstantValueType::String {
            length: Some(10),
            allowed_length_flag: 1,
        },
    ];
    for types in [
        &number_type[..],
        &reference_type[..],
        &[ConstantValueType::Boolean][..],
        &[ConstantValueType::DateTime {
            date_fractions: "Date",
        }][..],
    ] {
        assert_eq!(
            format_metadata_child_fill_value_xml(&empty, types, &MetadataTypeSetLeafIndex::new(),),
            r#"<FillValue xsi:nil="true"/>"#
        );
    }
    for types in [&string_type[..], &type_set[..], &mixed[..], &[][..]] {
        assert_eq!(
            format_metadata_child_fill_value_xml(&empty, types, &MetadataTypeSetLeafIndex::new(),),
            r#"<FillValue xsi:type="xs:string"/>"#
        );
    }
    // A non-empty string is the value itself whatever the declared type says.
    assert_eq!(
        format_metadata_child_fill_value_xml(
            &MetadataChildFillValue::String("x".to_string()),
            &number_type,
            &MetadataTypeSetLeafIndex::new(),
        ),
        r#"<FillValue xsi:type="xs:string">x</FillValue>"#
    );
}

/// Once the leaves a named type set declares are read, they decide the same
/// spelling the attribute's own primitive leaves decide.
///
/// Evidence, ERP УХ 3.2.12.6: `DataProcessors/ФормированиеЗаказовПоставщикуПоПлану`
/// carries `{"S",""}` on `Артикул`, whose declared type is
/// `DefinedType.Артикул` (`xs:string`), and the platform writes
/// `<FillValue xsi:type="xs:string"/>`;
/// `DataProcessors/ОтменаИсполненияПлатежныхПозиций` carries the very same
/// value on `Сумма`, whose declared type is
/// `DefinedType.ДенежнаяСуммаЛюбогоЗнака` (`xs:decimal`), and the platform
/// writes `<FillValue xsi:nil="true"/>`. Both attributes spell the identical
/// bare `{"Pattern",{"#",<uuid>}}`, so only the declaration of the named set
/// tells them apart.
#[test]
fn empty_string_fill_value_reads_the_leaves_a_named_type_set_declares() {
    let empty = MetadataChildFillValue::String(String::new());
    let article = [ConstantValueType::ReferenceTypeSet {
        reference: "cfg:DefinedType.Артикул".to_string(),
    }];
    let amount = [ConstantValueType::ReferenceTypeSet {
        reference: "cfg:DefinedType.ДенежнаяСуммаЛюбогоЗнака".to_string(),
    }];
    let leaves = MetadataTypeSetLeafIndex::from([
        (
            "cfg:DefinedType.Артикул".to_string(),
            vec![ConstantValueType::String {
                length: Some(25),
                allowed_length_flag: 1,
            }],
        ),
        (
            "cfg:DefinedType.ДенежнаяСуммаЛюбогоЗнака".to_string(),
            vec![ConstantValueType::Number {
                digits: 15,
                fraction_digits: 2,
                allowed_sign_flag: 0,
            }],
        ),
        // `Characteristic.X` is read the same way: the leaves are the chart's
        // own declared `<Type>`. `Characteristic.ВидыКонтроляДокументов` of
        // ERP УХ declares five catalogue references and no string, and the
        // platform writes the nil element for the register field that names it.
        (
            "cfg:Characteristic.ВидыКонтроляДокументов".to_string(),
            vec![ConstantValueType::Reference {
                reference: "cfg:CatalogRef.КлючиКонтроляПоДоговорам".to_string(),
            }],
        ),
        // A set whose own leaf names another set resolves through it.
        (
            "cfg:DefinedType.ЧерезДругой".to_string(),
            vec![ConstantValueType::ReferenceTypeSet {
                reference: "cfg:DefinedType.ДенежнаяСуммаЛюбогоЗнака".to_string(),
            }],
        ),
        // A set that names itself is a cycle and decides nothing.
        (
            "cfg:DefinedType.Кольцо".to_string(),
            vec![ConstantValueType::ReferenceTypeSet {
                reference: "cfg:DefinedType.Кольцо".to_string(),
            }],
        ),
    ]);

    assert_eq!(
        format_metadata_child_fill_value_xml(&empty, &article, &leaves),
        r#"<FillValue xsi:type="xs:string"/>"#
    );
    assert_eq!(
        format_metadata_child_fill_value_xml(&empty, &amount, &leaves),
        r#"<FillValue xsi:nil="true"/>"#
    );
    for reference in [
        "cfg:Characteristic.ВидыКонтроляДокументов",
        "cfg:DefinedType.ЧерезДругой",
    ] {
        assert_eq!(
            format_metadata_child_fill_value_xml(
                &empty,
                &[ConstantValueType::ReferenceTypeSet {
                    reference: reference.to_string(),
                }],
                &leaves,
            ),
            r#"<FillValue xsi:nil="true"/>"#,
            "{reference}"
        );
    }
    // A name the index cannot answer, and a cycle, keep the stored spelling.
    for reference in ["cfg:AnyIBRef", "cfg:DefinedType.Кольцо"] {
        assert_eq!(
            format_metadata_child_fill_value_xml(
                &empty,
                &[ConstantValueType::ReferenceTypeSet {
                    reference: reference.to_string(),
                }],
                &leaves,
            ),
            r#"<FillValue xsi:type="xs:string"/>"#,
            "{reference}"
        );
    }
    // One string leaf among several decides the whole list, whatever the set
    // beside it declares.
    assert_eq!(
        format_metadata_child_fill_value_xml(
            &empty,
            &[
                ConstantValueType::ReferenceTypeSet {
                    reference: "cfg:DefinedType.ДенежнаяСуммаЛюбогоЗнака".to_string(),
                },
                ConstantValueType::String {
                    length: Some(10),
                    allowed_length_flag: 1,
                },
            ],
            &leaves,
        ),
        r#"<FillValue xsi:type="xs:string"/>"#
    );
}

#[test]
fn parses_metadata_child_choice_parameter_links_from_wrapped_collection() {
    let object_refs = BTreeMap::from([
            (
                "fb9f5bff-ad18-4694-8e4f-9a8e7bd9aa5d".to_string(),
                "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.Attribute.Партнер".to_string(),
            ),
            (
                "acec7e3d-9efa-4656-84e3-e2f90b295e8a".to_string(),
                "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.TabularSection.Товары.Attribute.НоменклатураПартнера".to_string(),
            ),
            (
                "296cd400-da83-4189-a85c-0945600b3033".to_string(),
                "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.TabularSection.Товары.Attribute.Номенклатура".to_string(),
            ),
            (
                "0bb9272d-3127-4e50-8dc2-6651432168b0".to_string(),
                "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.TabularSection.Товары.Attribute.Характеристика".to_string(),
            ),
        ]);
    let links = parse_metadata_child_choice_parameter_links(
            Some(
                r##"{5006,3,"Отбор.ВладелецНоменклатуры",1,{0,fb9f5bff-ad18-4694-8e4f-9a8e7bd9aa5d},0,"Отбор.Номенклатура",2,{0,acec7e3d-9efa-4656-84e3-e2f90b295e8a},{0,296cd400-da83-4189-a85c-0945600b3033},1,"Отбор.Характеристика",2,{0,acec7e3d-9efa-4656-84e3-e2f90b295e8a},{0,0bb9272d-3127-4e50-8dc2-6651432168b0},1}"##,
            ),
            &object_refs,
            "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.",
        )
        .unwrap();

    assert_eq!(links.len(), 3);
    assert_eq!(links[0].name, "Отбор.ВладелецНоменклатуры");
    assert_eq!(
        links[0].data_path,
        "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.Attribute.Партнер"
    );
    assert_eq!(links[0].value_change, "Clear");
    assert_eq!(links[1].name, "Отбор.Номенклатура");
    assert_eq!(
        links[1].data_path,
        "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.TabularSection.Товары.Attribute.Номенклатура"
    );
    assert_eq!(links[1].value_change, "DontChange");
    assert_eq!(links[2].name, "Отбор.Характеристика");
    assert_eq!(
        links[2].data_path,
        "DataProcessor.ЗагрузкаТоваровИзВнешнихФайлов.TabularSection.Товары.Attribute.Характеристика"
    );
    assert_eq!(links[2].value_change, "DontChange");
}

/// A wrapped pair whose type the configuration does not carry keeps both
/// identifiers, and the same record shape with two *objects* stays the fixed
/// array it is.
///
/// Evidence, ERP УХ 3.3.3.3 `DataProcessors/ГенерацияКассовыхОрдеров`: the
/// attribute's two choice parameters store the identical shape.
/// `Отбор.ФормаОплаты` names `EnumRef.ФормыОплаты` beside a value and the
/// platform writes `Enum.ФормыОплаты.EnumValue.Наличная`;
/// `Отбор.СостояниеОбъекта` names `74217710-…`, which the whole native export
/// mentions only in that one file, and the platform writes the pair, although
/// its value identifier is a live enumeration value.
#[test]
fn metadata_choice_parameter_keeps_a_pair_whose_type_the_configuration_lost() {
    let stale_type = "74217710-53a3-4971-93c9-4bd74c53a81a";
    let live_type = "b3d3fa57-e3db-46d3-b7a9-68e89ebae723";
    let approved = "e8218ef1-026a-48b5-b5ca-934efd6df05e";
    let cash = "d450cea1-6bc0-427b-b3f6-68344c8dba57";
    let type_index =
        BTreeMap::from([(live_type.to_string(), "cfg:EnumRef.ФормыОплаты".to_string())]);
    let object_refs = BTreeMap::from([
        (
            approved.to_string(),
            "Enum.СостоянияСогласования.EnumValue.Утверждена".to_string(),
        ),
        (
            cash.to_string(),
            "Enum.ФормыОплаты.EnumValue.Наличная".to_string(),
        ),
    ]);
    let parameters = parse_metadata_child_choice_parameters(
        Some(&format!(
            r##"{{0,2,"Отбор.СостояниеОбъекта",{{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{{0,{stale_type},{approved}}}}},"Отбор.ФормаОплаты",{{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{{0,{live_type},{cash}}}}}}}"##
        )),
        &type_index,
        &object_refs,
    )
    .expect("both parameters parse");

    assert_eq!(parameters.len(), 2);
    assert!(
        matches!(
            &parameters[0].value,
            MetadataChoiceParameterValue::DesignTimeRef(value)
                if value == &format!("{stale_type}.{approved}")
        ),
        "the stale pair must be written physically"
    );
    assert!(
        matches!(
            &parameters[1].value,
            MetadataChoiceParameterValue::DesignTimeRef(value)
                if value == "Enum.ФормыОплаты.EnumValue.Наличная"
        ),
        "the live pair must resolve to its value's name"
    );
}

#[test]
fn parses_and_formats_metadata_child_choice_parameter_values() {
    let object_refs = BTreeMap::from([
        (
            "11111111-1111-4111-8111-111111111111".to_string(),
            "Enum.ФормыОплаты.EnumValue.Наличная".to_string(),
        ),
        (
            "22222222-2222-4222-8222-222222222222".to_string(),
            "Enum.ФормыОплаты.EnumValue.Безналичная".to_string(),
        ),
    ]);
    let parameters = parse_metadata_child_choice_parameters(
            Some(
                r##"{0,2,"Отбор.Клиент",{"B",1},"Отбор.Ссылка",{"#",4500381b-db30-4a10-9db4-990038032acf,{0,11111111-1111-4111-8111-111111111111,22222222-2222-4222-8222-222222222222}}}"##,
            ),
            &BTreeMap::new(),
            &object_refs,
        )
        .unwrap();

    assert_eq!(parameters.len(), 2);
    assert!(matches!(
        parameters[0].value,
        MetadataChoiceParameterValue::Boolean(true)
    ));
    assert!(matches!(
        parameters[1].value,
        MetadataChoiceParameterValue::FixedArray(ref refs)
            if matches!(
                refs.as_slice(),
                [
                    MetadataChoiceParameterValue::DesignTimeRef(first),
                    MetadataChoiceParameterValue::DesignTimeRef(second),
                ] if first == "Enum.ФормыОплаты.EnumValue.Наличная"
                    && second == "Enum.ФормыОплаты.EnumValue.Безналичная"
            )
    ));

    let mut xml = String::new();
    push_metadata_child_choice_parameters_xml(&mut xml, "\t\t\t", &parameters);
    assert!(xml.contains(r#"<app:value xsi:type="xs:boolean">true</app:value>"#));
    assert!(xml.contains(r#"<app:value xsi:type="v8:FixedArray">"#));
    assert!(xml.contains("Enum.ФормыОплаты.EnumValue.Наличная"));
    assert!(xml.contains("Enum.ФормыОплаты.EnumValue.Безналичная"));
}

/// A chart of characteristic types carries its data-lock mode in owner slot 36,
/// not slot 51: the 8.3.27.2214 `CorpusCharacteristics` corpus has `0` there and
/// exports `Automatic`, while this chart has `1` and exports `Managed`. Slot 51
/// is `1` in both, so it cannot carry the mode.
///
/// Provenance (`manifest.json` in the fixture directory): storage element
/// `dabae379-6356-497a-aab5-cf102f16a72a` of 1C:Trade Management 11.5.27.75's
/// `1cv8.cf`, packed body sha256
/// `6988feda821613ac0866240949273f7fb115f4ec8237a781bac30088751be053`; the
/// platform's own `ChartsOfCharacteristicTypes/ВопросыДляАнкетирования.xml`
/// from an `ibcmd config export` capture with 1C:Enterprise 8.3.27.2214
/// (sha256 `a2105a5985e5452e8c4004f2f04dcf552ff584bb07c38ac1772bec98662329f3`)
/// carries `<DataLockControlMode>Managed</DataLockControlMode>`.
#[test]
fn platform_chart_of_characteristic_types_carries_the_data_lock_mode_in_slot_36() {
    let packed = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "chart-of-characteristic-types-ut-managed-lock/raw-packed.bin.b64"
    )))
    .expect("platform-attested chart payload");
    assert_eq!(
        format!("{:x}", Sha256::digest(&packed)),
        "6988feda821613ac0866240949273f7fb115f4ec8237a781bac30088751be053"
    );
    let inflated = inflate_raw_deflate(&packed).expect("platform-attested chart raw-deflate body");
    assert_eq!(
        format!("{:x}", Sha256::digest(&inflated)),
        "e215b50a4b159affe09b6392b4d675aa5b17c9f5bc43be2053b759ad9e874395"
    );

    let text = String::from_utf8(inflated).expect("chart body is UTF-8");
    let body = text.trim_start_matches('\u{feff}');
    let header = parse_metadata_header_from_text(body, "dabae379-6356-497a-aab5-cf102f16a72a")
        .expect("chart header");
    let mut diagnostic = None;
    let owner_graph = decode_owner_graph_for_family_parser(
        owner_graph::OwnerGraphFamily::ChartOfCharacteristicTypes,
        body,
        &header,
        &mut diagnostic,
    )
    .expect("chart owner graph");

    assert_eq!(
        owner_graph.owner_fields.get(36).map(|field| field.trim()),
        Some("1")
    );
    assert_eq!(
        owner_graph.owner_fields.get(51).map(|field| field.trim()),
        Some("1")
    );
}

/// The atom that follows a link name is the data-path segment count, not the
/// change mode: a two-segment path with a trailing `0` is `Clear`. Wire and
/// expectation come from 1C:УТ 11.5.27.75
/// `DataProcessor.ПечатьЭтикетокИЦенников` (tabular section `Товары`).
#[test]
fn reads_metadata_child_link_change_mode_from_the_trailing_atom() {
    let object_refs = BTreeMap::from([
        (
            "4438e3aa-37d2-485b-9f8f-27653f9473b0".to_string(),
            "DataProcessor.ПечатьЭтикетокИЦенников.TabularSection.Товары".to_string(),
        ),
        (
            "4e5b7a37-6e75-430c-b26a-4a30b4d68f92".to_string(),
            "DataProcessor.ПечатьЭтикетокИЦенников.TabularSection.Товары.Attribute.Номенклатура"
                .to_string(),
        ),
    ]);
    let links = parse_metadata_child_choice_parameter_links(
        Some(
            r##"{5006,1,"Номенклатура",2,{0,4438e3aa-37d2-485b-9f8f-27653f9473b0},{0,4e5b7a37-6e75-430c-b26a-4a30b4d68f92},0}"##,
        ),
        &object_refs,
        "DataProcessor.ПечатьЭтикетокИЦенников.",
    )
    .unwrap();

    assert_eq!(links.len(), 1);
    assert_eq!(links[0].name, "Номенклатура");
    assert_eq!(
        links[0].data_path,
        "DataProcessor.ПечатьЭтикетокИЦенников.TabularSection.Товары.Attribute.Номенклатура"
    );
    assert_eq!(links[0].value_change, "Clear");
}

/// A literal string choice-parameter value is written as `{"S","<text>"}`, and a
/// fixed array keeps the order its members were written in. Wire and
/// expectations come from 1C:УТ 11.5.27.75 `DataProcessor.ПодборСерийВДокументы`
/// and `DataProcessor.ГенерацияТопологииСклада`.
#[test]
fn parses_string_and_ordered_fixed_array_choice_parameter_values() {
    let object_refs = BTreeMap::from([
        (
            "aaf17114-0c7a-4709-bc08-5b3eac621a02".to_string(),
            "Enum.НастройкиАдресногоХранения.EnumValue.ЯчейкиСправочно".to_string(),
        ),
        (
            "ee67d3ea-8ef0-4319-ad37-83a152d02237".to_string(),
            "Enum.НастройкиАдресногоХранения.EnumValue.ЯчейкиОстатки".to_string(),
        ),
        (
            "547ae60a-335d-4529-8a04-c07afb777818".to_string(),
            "Enum.НастройкиАдресногоХранения.EnumValue.ОпределяетсяНастройкамиПомещения"
                .to_string(),
        ),
    ]);
    let parameters = parse_metadata_child_choice_parameters(
        Some(
            r##"{0,2,"РежимВыбораНазначений",{"S","Все"},"АдресноеХранение",{"#",4500381b-db30-4a10-9db4-990038032acf,{3,{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{0,09b67064-0478-4ebf-a7a9-1f06d3b62882,aaf17114-0c7a-4709-bc08-5b3eac621a02}},{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{0,09b67064-0478-4ebf-a7a9-1f06d3b62882,ee67d3ea-8ef0-4319-ad37-83a152d02237}},{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{0,09b67064-0478-4ebf-a7a9-1f06d3b62882,547ae60a-335d-4529-8a04-c07afb777818}}}}}"##,
        ),
        &BTreeMap::new(),
        &object_refs,
    )
    .unwrap();

    assert_eq!(parameters.len(), 2);
    assert!(matches!(
        parameters[0].value,
        MetadataChoiceParameterValue::String(ref text) if text == "Все"
    ));
    let MetadataChoiceParameterValue::FixedArray(ref members) = parameters[1].value else {
        panic!("second choice parameter must decode as a fixed array");
    };
    assert_eq!(
        members
            .iter()
            .map(|member| match member {
                MetadataChoiceParameterValue::DesignTimeRef(value) => value.as_str(),
                _ => panic!("fixed-array member must be a design-time reference"),
            })
            .collect::<Vec<_>>(),
        [
            "Enum.НастройкиАдресногоХранения.EnumValue.ЯчейкиСправочно",
            "Enum.НастройкиАдресногоХранения.EnumValue.ЯчейкиОстатки",
            "Enum.НастройкиАдресногоХранения.EnumValue.ОпределяетсяНастройкамиПомещения",
        ]
    );

    let mut xml = String::new();
    push_metadata_child_choice_parameters_xml(&mut xml, "\t\t\t", &parameters);
    assert!(
        xml.contains(r#"<app:value xsi:type="xs:string">Все</app:value>"#),
        "{xml}"
    );
}

/// The wrapped data-processor child uses the same flat property layout the
/// register and document decoders already prove. Wire and expectations come
/// from 1C:УТ 11.5.27.75 `DataProcessor.ПечатьЭтикетокИЦенников`, attribute
/// `Склад`.
#[test]
fn wrapped_data_processor_child_reads_the_proven_property_slots() {
    let object_refs = BTreeMap::from([(
        "1b09dfb7-8fec-4ddf-8f7f-2285584cea0b".to_string(),
        "Enum.ТипыСкладов.EnumValue.РозничныйМагазин".to_string(),
    )]);
    let fields = [
        "2",
        r##"{3,{1,0,2aa2ee52-b373-4c46-98f3-faffeb07fa88},"Склад",{1,"ru","Розничный магазин"},"",0,0,00000000-0000-0000-0000-000000000000,0}"##,
        r##"{"Pattern",{"#",e63fc7d1-3d01-4fbb-8cbe-9d4bf8fe2126}}"##,
        "0",
        "{0}",
        "{0}",
        "0",
        r#""""#,
        "0",
        r#"{"U"}"#,
        r#"{"U"}"#,
        "2",
        "00000000-0000-0000-0000-000000000000",
        "2",
        "0",
        "{5006,0}",
        "{3,0,0}",
        r##"{0,1,"Отбор.ТипСклада",{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{0,d19811b1-1650-47cd-a01c-a79958cb224c,1b09dfb7-8fec-4ddf-8f7f-2285584cea0b}}}"##,
        "0",
        "{0}",
        r#"{"S",""}"#,
        "0",
        "0",
        "0",
    ];

    // The choice parameter names the enumeration's `Ref` type beside the
    // value, so the type index carries it: a pair whose type the
    // configuration does not carry is the one the platform writes as an
    // identifier pair (`unnameable_metadata_design_time_pair`), which is not
    // the case this fixture is about.
    let type_index = BTreeMap::from([(
        "d19811b1-1650-47cd-a01c-a79958cb224c".to_string(),
        "cfg:EnumRef.ТипыСкладов".to_string(),
    )]);
    let properties = parse_data_processor_wrapped_child_properties(
        &fields,
        1,
        "DataProcessor.Owner.",
        &[],
        &type_index,
        &object_refs,
        &object_refs,
        &BTreeMap::new(),
    )
    .expect("wrapped data-processor child layout");

    assert_eq!(properties.choice_folders_and_items, Some("FoldersAndItems"));
    assert!(
        properties
            .choice_parameter_links
            .as_deref()
            .is_some_and(<[_]>::is_empty)
    );
    assert!(properties.link_by_type_empty);
    assert!(properties.link_by_type.is_none());
    assert_eq!(properties.quick_choice, Some("Auto"));
    assert_eq!(properties.create_on_input, Some("Auto"));
    assert_eq!(properties.choice_history_on_input, Some("Auto"));
    assert!(!properties.fill_from_filling_value);
    assert!(!properties.extended_edit);
    let parameters = properties
        .choice_parameters
        .as_deref()
        .expect("choice parameters");
    assert_eq!(parameters.len(), 1);
    assert_eq!(parameters[0].name, "Отбор.ТипСклада");
    assert!(matches!(
        parameters[0].value,
        MetadataChoiceParameterValue::DesignTimeRef(ref value)
            if value == "Enum.ТипыСкладов.EnumValue.РозничныйМагазин"
    ));
}

fn generated_type_source_row(file_name: &str, type_id: &str, name: &str) -> MetadataTextRow {
    MetadataTextRow {
        file_name: file_name.to_string(),
        text: format!(
            r#"<MetaDataObject xmlns:xr="http://v8.1c.ru/8.3/xcf/readable"><Catalog><InternalInfo><xr:GeneratedType name="{name}" category="Ref"><xr:TypeId>{type_id}</xr:TypeId></xr:GeneratedType></InternalInfo></Catalog></MetaDataObject>"#
        ),
        object_code: None,
        header: None,
        kind: Some("Catalog".to_string()),
        folder: Some("Catalogs"),
    }
}

#[test]
fn generated_type_builder_records_collisions_without_changing_last_writer_indexes() {
    let duplicate_id = "190a7469-3325-4d33-b5ec-28a63ac83b06";
    let unique_id = "290a7469-3325-4d33-b5ec-28a63ac83b06";
    let rows = [
        generated_type_source_row("first", duplicate_id, "CatalogRef.First"),
        generated_type_source_row(
            "second",
            &duplicate_id.to_ascii_uppercase(),
            "CatalogRef.Second",
        ),
        generated_type_source_row("unique", unique_id, "CatalogRef.Unique"),
    ];
    let indexes = build_metadata_type_indexes_from_texts(&rows);

    assert_eq!(
        indexes.references.get(duplicate_id).map(String::as_str),
        Some("cfg:CatalogRef.Second")
    );
    assert!(indexes.reference_collisions.contains(duplicate_id));
    assert!(!indexes.reference_collisions.contains(unique_id));
    assert!(matches!(
        indexes.dcs.get(duplicate_id),
        Some(DcsTypeResolution::Type { qname }) if qname == "cfg:CatalogRef.Second"
    ));

    let same_qname = build_metadata_type_indexes_from_texts(&[
        generated_type_source_row("same-first", duplicate_id, "CatalogRef.Same"),
        generated_type_source_row(
            "same-second",
            &duplicate_id.to_ascii_uppercase(),
            "CatalogRef.Same",
        ),
    ]);
    assert!(same_qname.reference_collisions.contains(duplicate_id));
    assert_eq!(
        same_qname.references.get(duplicate_id).map(String::as_str),
        Some("cfg:CatalogRef.Same")
    );
}

