#[test]
fn formats_moxel_multiple_column_sets_do_not_synthesize_default_format_index() {
    let column_sets = vec![
        MoxelColumnSet {
            id: None,
            default_format_index: None,
            raw_default_format_index: 0,
            size: 1,
            columns: vec![MoxelColumn {
                index: 0,
                format_index: 1,
                source_format_index: None,
            }],
        },
        MoxelColumnSet {
            id: Some("5c3926f2-4223-4ca7-a6a7-7160301c991d".to_string()),
            default_format_index: None,
            raw_default_format_index: 0,
            size: 4,
            columns: vec![
                MoxelColumn {
                    index: 0,
                    format_index: 2,
                    source_format_index: None,
                },
                MoxelColumn {
                    index: 4,
                    format_index: 6,
                    source_format_index: None,
                },
            ],
        },
    ];
    let settings = MoxelPrintSettings::default();

    assert_eq!(
        moxel_default_format_index(&column_sets, Some(&settings), false, 21),
        None
    );
    assert_eq!(
        moxel_default_format_index(&column_sets, Some(&settings), true, 21),
        Some(21)
    );
    assert_eq!(
        moxel_default_format_index(&column_sets, None, false, 21),
        None
    );
}

#[test]
fn formats_moxel_picture_drawing_and_normalized_picture_index() {
    // `<zOrder>` is the drawing's position in the sequence, so the ordinal is
    // assigned by the sequence reader rather than by the record decoder.
    let drawings = parse_moxel_drawings(
        &["{{0,31},5,1,20,24,6,1,20,88,70,1,1,1,0}"],
        &BTreeMap::new(),
    );
    assert_eq!(drawings.len(), 1);
    let drawing = drawings.into_iter().next().unwrap();

    assert_eq!(drawing.id, 1);
    assert_eq!(drawing.format_index, 31);
    assert_eq!(drawing.begin_row, 20);
    assert_eq!(drawing.begin_row_offset, 6);
    assert_eq!(drawing.end_row, 20);
    assert_eq!(drawing.end_row_offset, 70);
    assert_eq!(drawing.begin_column, 1);
    assert_eq!(drawing.begin_column_offset, 24);
    assert_eq!(drawing.end_column, 1);
    assert_eq!(drawing.end_column_offset, 88);
    assert!(!drawing.auto_size);
    let MoxelDrawingKind::Picture {
        picture_size,
        picture_index,
    } = &drawing.kind
    else {
        panic!("expected picture drawing");
    };
    assert_eq!(*picture_size, "Stretch");
    assert_eq!(drawing.z_order, 1);
    assert_eq!(*picture_index, 1);

    let mut xml = String::new();
    push_moxel_drawing_xml(&mut xml, &drawing, &BTreeMap::new());
    assert!(xml.contains("<drawingType>Picture</drawingType>"));
    assert!(xml.contains("<id>1</id>"));
    assert!(xml.contains("<formatIndex>31</formatIndex>"));
    assert!(xml.contains("<beginRow>20</beginRow>"));
    assert!(xml.contains("<beginRowOffset>6</beginRowOffset>"));
    assert!(xml.contains("<endRowOffset>70</endRowOffset>"));
    assert!(xml.contains("<beginColumn>1</beginColumn>"));
    assert!(xml.contains("<beginColumnOffset>24</beginColumnOffset>"));
    assert!(xml.contains("<endColumnOffset>88</endColumnOffset>"));
    assert!(xml.contains("<autoSize>false</autoSize>"));
    assert!(xml.contains("<pictureSize>Stretch</pictureSize>"));
    assert!(xml.contains("<zOrder>1</zOrder>"));
    assert!(xml.contains("<pictureIndex>1</pictureIndex>"));

    let real_size = parse_moxel_drawings(
        &["{{0,137},5,7,1,6,3,11,3,66,54,2,1,0,0}"],
        &BTreeMap::new(),
    )
    .into_iter()
    .next()
    .unwrap();
    assert_eq!(real_size.id, 2);
    assert!(matches!(
        real_size.kind,
        MoxelDrawingKind::Picture {
            picture_size: "RealSize",
            picture_index: 1
        }
    ));
    assert_eq!(real_size.z_order, 1);
    assert!(!real_size.auto_size);

    let proportional = parse_moxel_drawings(
        &["{{0,77},5,1,9,21,9,6,14,12,66,10,1,2,0}"],
        &BTreeMap::new(),
    )
    .into_iter()
    .next()
    .unwrap();
    assert_eq!(proportional.id, 10);
    assert!(matches!(
        proportional.kind,
        MoxelDrawingKind::Picture {
            picture_size: "Proportionally",
            picture_index: 1
        }
    ));
    assert_eq!(proportional.z_order, 1);
    assert!(!proportional.auto_size);

    let auto_size = parse_moxel_drawings(
        &["{{0,44},5,5,26,27,30,37,26,15,720,1,1,4,0}"],
        &BTreeMap::new(),
    )
    .into_iter()
    .next()
    .unwrap();
    assert_eq!(auto_size.id, 1);
    assert!(matches!(
        auto_size.kind,
        MoxelDrawingKind::Picture {
            picture_size: "AutoSize",
            picture_index: 1
        }
    ));
    assert_eq!(auto_size.z_order, 1);
    assert!(!auto_size.auto_size);

    let pictures = parse_moxel_pictures(
        &[
            "1",
            "{4,1,{0,b5e73fbe-499c-4666-a482-0ef399c97c1e},\"\",-1,-1,0,0,\"\"}",
        ],
        &BTreeMap::from([(
            "b5e73fbe-499c-4666-a482-0ef399c97c1e".to_string(),
            "CommonPicture.Предупреждение32".to_string(),
        )]),
    );
    assert_eq!(pictures.len(), 1);
    assert_eq!(pictures[0].index, 0);
    assert_eq!(
        pictures[0].ref_name.as_deref(),
        Some("v8ui:Предупреждение32")
    );
}

/// Evidence (БСП демо 3.1.12.297, `_ДемоСчетНаОплатуПокупателю/.../
/// ПФ_MXL_СчетЗаказ`): two `Text` drawings carry an explicitly empty
/// `parameter` value (`ФИОРуководителя`, `ФИОБухгалтера`) and the platform
/// self-closes it, `<value xsi:type="xs:string"/>`, the same spelling the
/// cell `<v>`/`<d>` writer already used for an empty string. The drawing
/// writer instead always wrote the open/close pair with empty content
/// between, `<value xsi:type="xs:string"></value>` -- a real byte
/// divergence, not a semantic no-op, since the platform never writes that
/// second spelling for this element.
#[test]
fn self_closes_empty_string_drawing_value() {
    let drawing = MoxelDrawing {
        id: 12,
        format_index: 58,
        begin_row: 48,
        begin_row_offset: 10,
        end_row: 49,
        end_row_offset: 0,
        begin_column: 6,
        begin_column_offset: 8,
        end_column: 16,
        end_column_offset: 26,
        auto_size: false,
        z_order: 4,
        members: MoxelDrawingMembers {
            text: Vec::new(),
            text_present: false,
            parameter: Some("ФИОРуководителя".to_string()),
            value: Some(String::new()),
            detail_parameter: None,
        },
        kind: MoxelDrawingKind::Shape("Text"),
    };
    let mut xml = String::new();
    push_moxel_drawing_xml(&mut xml, &drawing, &BTreeMap::new());
    assert!(
        xml.contains("<value xsi:type=\"xs:string\"/>\r\n"),
        "empty drawing value must self-close like the cell value writer does: {xml}"
    );
    assert!(!xml.contains("<value xsi:type=\"xs:string\"></value>"));
}

#[test]
fn rejects_malformed_or_unbounded_moxel_chart_drawings() {
    let chart_type = "a8b97779-1a4b-4059-b09c-807f86d2a461";
    assert!(
        parse_moxel_drawing(
            &format!("{{{{0,60}},10,1,4,9,15,1,12,759,33,1,{chart_type},{{{{11}},{{74}}}},0}}"),
            &BTreeMap::new()
        )
        .is_none()
    );
    let oversized = "0".repeat(1024 * 1024 + 1);
    assert!(
        parse_moxel_drawing(
            &format!("{{{{0,60}},10,1,4,9,15,1,12,759,33,1,{chart_type},{oversized},0}}"),
            &BTreeMap::new()
        )
        .is_none()
    );
}

#[test]
fn normalizes_moxel_chart_scientific_decimals_canonically() {
    assert_eq!(
        normalize_moxel_chart_decimal("2e3"),
        Some("2000".to_string())
    );
    assert_eq!(
        normalize_moxel_chart_decimal("1e-1"),
        Some("0.1".to_string())
    );
    assert_eq!(
        moxel_chart_fraction_to_percent("1e-1"),
        Some("10".to_string())
    );
    assert_eq!(normalize_moxel_chart_decimal("1e2147483647"), None);
    assert_eq!(normalize_moxel_chart_decimal("1e-2147483648"), None);
    assert_eq!(
        normalize_moxel_chart_decimal("1e999999999999999999999"),
        None
    );
    assert_eq!(normalize_moxel_chart_decimal("1e4096"), None);
    assert_eq!(normalize_moxel_chart_decimal("1e-4096"), None);
    assert_eq!(normalize_moxel_chart_decimal("-1e4095"), None);
    let largest_bounded = normalize_moxel_chart_decimal("1e4095")
        .expect("bounded output at the maximum length must remain supported");
    assert_eq!(largest_bounded.len(), 4096);
}

#[test]
fn formats_moxel_prefers_leading_width_only_source_column_formats() {
    let formats = vec![
        MoxelFormat {
            width: Some(8),
            ..MoxelFormat::default()
        },
        MoxelFormat {
            width: Some(19),
            ..MoxelFormat::default()
        },
        MoxelFormat {
            back_color: Some("style:ToolTipBackColor".to_string()),
            ..MoxelFormat::default()
        },
        MoxelFormat {
            width: Some(19),
            ..MoxelFormat::default()
        },
    ];

    assert!(prefers_moxel_leading_source_column_formats(
        &formats,
        &[1, 2]
    ));
    let (column_formats, other_formats) = split_moxel_formats_by_source_refs(formats, &[1, 2]);
    assert_eq!(column_formats.len(), 2);
    assert_eq!(column_formats[0].width, Some(8));
    assert_eq!(column_formats[1].width, Some(19));
    assert_eq!(other_formats.len(), 2);
    assert_eq!(
        other_formats[0].back_color.as_deref(),
        Some("style:ToolTipBackColor")
    );
}

/// Fixture: `tests/fixtures/moxel_file_transfer_report_raw.txt`, 1159 bytes,
/// sha256
/// `5cc5db95436638be41bd6ddf85a05e6299876c26f3a3904576d0e07872ba3b46`. It is the
/// complete native MOXCEL body of the `МакетОтчета` template of data processor
/// `ПереносФайлов` in 1С:Управление торговлей 11.5.27.75 (`1cv8.cf`), as
/// produced by this project's compatible-MXL decoder.
///
/// The body this test used to carry was that one with five spans cut out of it,
/// among them the whole `{3,0,<nil>,3,0,5,1,6,2,7}` columns record - a body the
/// platform never writes, and whose expected numbering could therefore only
/// ever have been this reader's own. Every assertion below now holds against
/// the platform's own bytes for the complete body: the `<formatIndex>5</...>`
/// on the third row and the `<f>6</f>` on the cell carrying the detail
/// parameter are the pool positions the platform itself publishes.
#[test]
fn formats_moxel_detail_parameters_and_row_format_offsets() {
    let spreadsheet = parse_moxel_spreadsheet_text(
        include_str!("../../tests/fixtures/moxel_file_transfer_report_raw.txt"),
        &BTreeMap::new(),
    )
    .unwrap();
    let xml = format_moxel_spreadsheet_xml(&spreadsheet);

    assert!(xml.contains("<index>2</index>\r\n\t\t<row>\r\n\t\t\t<formatIndex>5</formatIndex>"));
    assert!(xml.contains(
        "<f>6</f>\r\n\t\t\t\t\t<parameter>Название</parameter>\r\n\t\t\t\t\t<detailParameter>Версия</detailParameter>"
    ));
    assert!(xml.contains("\t<format>\r\n\t\t<font>0</font>\r\n\t</format>"));
    assert!(xml.contains("\t<format>\r\n\t\t<height>54</height>\r\n\t</format>"));
    assert!(xml.contains(
        "\t<format>\r\n\t\t<verticalAlignment>Top</verticalAlignment>\r\n\t\t<textPlacement>Wrap</textPlacement>\r\n\t\t<fillType>Parameter</fillType>\r\n\t\t<hyperLink>true</hyperLink>\r\n\t</format>"
    ));
    assert!(xml.contains("\t<format>\r\n\t\t<width>318</width>\r\n\t</format>"));
    assert!(xml.contains("<defaultFormatIndex>8</defaultFormatIndex>"));
    assert!(!xml.contains("<line width=\"1\""));
}

