#[test]
fn writes_business_process_flowchart_to_source_layout() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    let _scratch = crate::test_scratch::TestScratch::adopt(&root);
    fs::create_dir_all(&root).unwrap();
    let process_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let start_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let completion_uuid = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let metadata = deflate_for_test(
            format!(
                "{{1,\r\n{{30,\r\n{{3,\r\n{{1,0,{process_uuid}}},\"Approval\",{{1,\"en\",\"Approval\"}},\"\"}}\r\n}}\r\n}}"
            )
            .as_bytes(),
        );
    let style = "{7,{3,4,{0}},{3,3,{-22}},{3,3,{-3}},{7,1,0,{0},1,100},{1,0},1,1,1,0,0,0,0,0}";
    let line_style = "{7,{3,0,{0}},{3,3,{-22}},{3,3,{-3}},{7,1,0,{0},1,100},{1,0},1,1,1,1,0,0,0,0}";
    let border = "{4,0,{0},1,1,0,e45c0cd8-a878-4bcb-8e1a-af934481e1cc,0}";
    let start_head = format!("{{{{4,1,{{1,0}},\"Start\",1}},4,{start_uuid},0}}");
    let completion_head = format!("{{{{4,3,{{1,0}},\"Done\",3}},4,{completion_uuid},0}}");
    let line_head = "{4,2,{1,0},\"Line\",2}";
    let picture = "{4,0,{0},\"\",-1,-1,1,0,\"\"}";
    let start_geometry =
        format!("{{{style},5,10,20,50,60,4,10,20,49,20,49,59,10,59,4,{picture},{border}}}");
    let completion_geometry =
        format!("{{{style},5,70,80,110,120,4,70,80,109,80,109,119,70,119,4,{picture},{border}}}");
    let start_shape = format!("{{{{{start_geometry},1}}}}");
    let completion_shape = format!("{{{{{completion_geometry},1}}}}");
    let line_geometry = format!("{{{line_style},6,2,50,60,70,80,{border},0,4,2,0,0,1}}");
    let line_shape = format!("{{{line_geometry}}}");
    let start_item = format!("{{{start_head},2,{start_shape},{{0}}}}");
    let line_item = format!("{{{line_head},3,1,0,3,0,{line_shape}}}");
    let completion_item =
        format!("{{{completion_head},2,{completion_shape},{{1,{{0,\"OnDone\"}}}}}}");
    let flowchart = deflate_for_test(
        format!(
            "{{5,{{{{1,{{3,3,{{-10}}}},1,20,20,3,6,6,{{\"N\",10}},7,{{\"N\",10}},8,{{\"N\",10}},9,{{\"N\",10}},13,{{\"N\",0}},16,{{\"N\",0}}}}}},3,2,{start_item},1,{line_item},3,{completion_item},4}}"
        )
        .as_bytes(),
    );
    let rows = vec![
        ConfigRow {
            file_name: process_uuid.to_string(),
            part_no: 0,
            data_size: metadata.len() as i64,
            binary_hex: encode_hex_for_test(&metadata),
        },
        ConfigRow {
            file_name: format!("{process_uuid}.7"),
            part_no: 0,
            data_size: flowchart.len() as i64,
            binary_hex: encode_hex_for_test(&flowchart),
        },
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert_eq!(dumped.source_asset_rows, 1);
    let xml =
        fs::read_to_string(root.join("BusinessProcesses/Approval/Ext/Flowchart.xml")).unwrap();
    assert!(xml.contains(r#"<Start id="1" uuid="bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb">"#));
    assert!(xml.contains(r#"<ConnectionLine id="2">"#));
    let line_xml = xml
        .split(r#"<ConnectionLine id="2">"#)
        .nth(1)
        .unwrap()
        .split("</ConnectionLine>")
        .next()
        .unwrap();
    assert!(line_xml.contains("<ZOrder>1</ZOrder>"));
    assert!(xml.contains("<Item>Start</Item>"));
    assert!(xml.contains("<Item>Done</Item>"));
    assert!(xml.contains(r#"<Completion id="3" uuid="cccccccc-cccc-4ccc-cccc-cccccccccccc">"#));
    assert!(xml.contains(r#"<Event name="OnComplete">OnDone</Event>"#));
    let flowchart_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{process_uuid}.7"))
        .unwrap();
    assert_eq!(
        flowchart_row.source_asset_path.as_deref(),
        Some("BusinessProcesses/Approval/Ext/Flowchart.xml")
    );
}

/// The `ChoiceParameters` slot of a standard attribute, as the platform
/// stores it on Catalogs/ПрочиеРасходы of 1C:Trade Management 11.5.27.75:
/// a typed value wrapping the `{0,count,name,value,...}` list. With a
/// resolution scope the entries decode through the shared reader; without
/// one only the empty list is admissible, which keeps every family that
/// cannot resolve references refusing instead of guessing.
#[test]
fn standard_attribute_choice_parameters_decode_with_scope_and_refuse_without() {
    let value = concat!(
        r##"{"#",f2eaae14-91a7-47b9-9d69-097877f41580,"##,
        r##"{0,2,"Отбор.ВариантРаспределенияРасходов","##,
        r##"{"#",5c14e26f-099b-4d37-84a6-b433d87400da,"##,
        r##"{0,8815e93c-5119-4e6a-92b1-20bc3bd09cd4,805eda2b-2e89-43f7-a430-445dc577611a}"##,
        r##"},"Отбор.ПрочиеРасходы",{"B",1}}}"##,
    );
    let empty = r##"{"#",f2eaae14-91a7-47b9-9d69-097877f41580,{0,0}}"##;
    let type_index = BTreeMap::from([(
        "8815e93c-5119-4e6a-92b1-20bc3bd09cd4".to_string(),
        "cfg:EnumRef.ВариантыРаспределенияРасходов".to_string(),
    )]);
    let object_refs = BTreeMap::from([(
        "805eda2b-2e89-43f7-a430-445dc577611a".to_string(),
        "Enum.ВариантыРаспределенияРасходов.EnumValue.НаНаправленияДеятельности".to_string(),
    )]);
    let scope = StandardAttributeChoiceParameterScope {
        type_index: &type_index,
        object_refs: &object_refs,
    };

    let parameters =
        parse_register_standard_attribute_choice_parameters(value, Some(scope)).unwrap();
    assert_eq!(parameters.len(), 2);
    assert_eq!(parameters[0].name, "Отбор.ВариантРаспределенияРасходов");
    assert!(matches!(
        &parameters[0].value,
        MetadataChoiceParameterValue::DesignTimeRef(reference)
            if reference == "Enum.ВариантыРаспределенияРасходов.EnumValue.НаНаправленияДеятельности"
    ));
    assert_eq!(parameters[1].name, "Отбор.ПрочиеРасходы");
    assert!(matches!(
        &parameters[1].value,
        MetadataChoiceParameterValue::Boolean(true)
    ));

    assert!(
        parse_register_standard_attribute_choice_parameters(empty, Some(scope))
            .is_some_and(|parameters| parameters.is_empty())
    );
    assert!(
        parse_register_standard_attribute_choice_parameters(empty, None)
            .is_some_and(|parameters| parameters.is_empty())
    );
    assert!(parse_register_standard_attribute_choice_parameters(value, None).is_none());
}

/// Platform-attested storage element `553dbd65-c1aa-406a-8ccc-ca1538267b13.7`
/// (BusinessProcesses/СогласованиеЦенНоменклатуры flowchart, packed sha256
/// `25d6dadb85e615447be742ab46871edbf22646bdbd8fe7564b3fdfb370c42d51`) of
/// 1C:Trade Management 11.5.27.75's `1cv8.cf`. Its native export (sha256
/// `960ffec593f87052800302cac35025ee00000e38915cf315e4dd561e4b872673`,
/// byte-identical to manifest-round2 of the same platform export) is
/// reproduced byte-for-byte: the byte-order mark, the print parameters, the
/// automatic font, the addressing-attribute design-time reference to the
/// predefined executor role, and the absence of a trailing newline.
#[test]
fn platform_business_process_flowchart_reencodes_byte_for_byte() {
    let packed = decode_base64_mime(include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "business-process-flowchart-ut/raw/553dbd65-c1aa-406a-8ccc-ca1538267b13.7.deflate.b64"
    )))
    .expect("platform-attested flowchart payload");
    assert_eq!(
        format!("{:x}", Sha256::digest(&packed)),
        "25d6dadb85e615447be742ab46871edbf22646bdbd8fe7564b3fdfb370c42d51"
    );
    let inflated =
        inflate_raw_deflate(&packed).expect("platform-attested flowchart raw-deflate body");
    assert_eq!(
        format!("{:x}", Sha256::digest(&inflated)),
        "9dee730eca1cf684bf93a260b2eef514fb3bb62acc3d5cadeb57a397116439e5"
    );
    let text = String::from_utf8(inflated).expect("flowchart body is UTF-8");

    // The reference slice the export pipeline resolves this flowchart with:
    // the four task addressing attributes, the executor-role catalog behind
    // the design-time value, and its predefined item.
    let object_refs = BTreeMap::from(
        [
            (
                "0408002c-9255-43a2-8022-82f02ee0e8f4",
                "Task.ЗадачаИсполнителя.AddressingAttribute.ДополнительныйОбъектАдресации",
            ),
            (
                "1851afd4-5324-45c1-b754-54e65943f945",
                "Task.ЗадачаИсполнителя.AddressingAttribute.ОсновнойОбъектАдресации",
            ),
            (
                "88f44c9b-216d-4d7e-bc88-1e6b253ed01e",
                "Task.ЗадачаИсполнителя.AddressingAttribute.Исполнитель",
            ),
            (
                "bc5eca9b-32d8-44e0-a127-8ad1f47d7957",
                "Task.ЗадачаИсполнителя.AddressingAttribute.РольИсполнителя",
            ),
            (
                "44422b6d-5eb8-49c6-856b-dd9009611933",
                "Catalog.РолиИсполнителей",
            ),
            (
                "owner-value:Catalog.РолиИсполнителей:15f28b3a-2fbc-42f0-80b9-508b588438b1",
                "Catalog.РолиИсполнителей.СогласующийУстановкиЦенНоменклатуры",
            ),
        ]
        .map(|(key, value)| (key.to_string(), value.to_string())),
    );

    let flowchart =
        parse_business_process_flowchart_text(text.trim_start_matches('\u{feff}'), &object_refs)
            .expect("the platform flowchart parses whole");
    let xml = format_business_process_flowchart_xml(&flowchart);
    let native: &[u8] = include_bytes!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "business-process-flowchart-ut/native/BusinessProcesses/",
        "СогласованиеЦенНоменклатуры/Ext/Flowchart.xml"
    ));
    assert_eq!(
        format!("{:x}", Sha256::digest(native)),
        "960ffec593f87052800302cac35025ee00000e38915cf315e4dd561e4b872673",
        "bundled native evidence must stay byte-identical to the platform export"
    );
    assert_eq!(xml.as_bytes(), native);
}

/// A standalone `GraphicalSchema` template body decodes through the same
/// grammar and is reproduced byte-for-byte. Документооборот КОРП 3.0.21.3,
/// `Catalogs/СхемыПроцессов/Templates/ШаблонЭлементаДекорация`: one
/// `Decoration` whose stored figure is `11`, which the platform exports as
/// `<Shape>Block</Shape>` -- the value that refused the whole scheme while
/// the decoder admitted only figure `10`.
#[test]
fn platform_graphical_scheme_template_reencodes_byte_for_byte() {
    let text = include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "graphical-scheme-do/raw/ШаблонЭлементаДекорация.scheme.txt"
    ));
    assert_eq!(
        format!("{:x}", Sha256::digest(text.as_bytes())),
        "293327995a04b0c6718092a14fe4c4b51d90930d55fe05419c5db8aa08e8b47e"
    );
    assert!(looks_like_graphical_scheme_blob_text(
        text.trim_start_matches('\u{feff}').trim_start()
    ));
    let flowchart = parse_business_process_flowchart_text(
        text.trim_start_matches('\u{feff}').trim_start(),
        &BTreeMap::new(),
    )
    .expect("the platform graphical scheme parses whole");
    let native: &[u8] = include_bytes!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "graphical-scheme-do/native/Catalogs/СхемыПроцессов/Templates/",
        "ШаблонЭлементаДекорация/Ext/Template.xml"
    ));
    assert_eq!(
        format!("{:x}", Sha256::digest(native)),
        "44b0477f3ae332704f72415230dab4eb6751e01ecd5283d0864d64a201618013",
        "bundled native evidence must stay byte-identical to the platform export"
    );
    assert_eq!(
        format_business_process_flowchart_xml(&flowchart).as_bytes(),
        native
    );
}

/// The route map that carries the `Switch` item (code 6), which the decoder
/// did not know at all, and activities whose addressing-attribute collection
/// declares two members rather than the four ERP УХ writes.
/// Документооборот КОРП 3.0.21.3, `BusinessProcesses/Рассмотрение`.
#[test]
fn platform_graphical_scheme_switch_item_reencodes_byte_for_byte() {
    let text = include_str!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "graphical-scheme-do/raw/Рассмотрение.flowchart.txt"
    ));
    assert_eq!(
        format!("{:x}", Sha256::digest(text.as_bytes())),
        "93a484597aa9931da53ee8dcf500d2b0255e708fb95f4fa790aa5a6ab8c4e4e6"
    );
    let object_refs = BTreeMap::from(
        [
            (
                "88f44c9b-216d-4d7e-bc88-1e6b253ed01e",
                "Task.ЗадачаИсполнителя.AddressingAttribute.Исполнитель",
            ),
            (
                "d4ddd77f-0a21-4e76-9e66-1bb76edd257d",
                "Task.ЗадачаИсполнителя.AddressingAttribute.РольИсполнителя",
            ),
        ]
        .map(|(key, value)| (key.to_string(), value.to_string())),
    );
    let flowchart = parse_business_process_flowchart_text(
        text.trim_start_matches('\u{feff}').trim_start(),
        &object_refs,
    )
    .expect("the platform route map parses whole");
    assert!(
        flowchart.items.iter().any(|item| item.tag == "Switch"),
        "the route map must publish the Switch item the decoder gained"
    );
    let native: &[u8] = include_bytes!(concat!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/",
        "graphical-scheme-do/native/BusinessProcesses/Рассмотрение/Ext/Flowchart.xml"
    ));
    assert_eq!(
        format!("{:x}", Sha256::digest(native)),
        "12e61b06ae0b52fa264e9e73f08aa1134442d2fea9772d0a5063fed74f762d83",
        "bundled native evidence must stay byte-identical to the platform export"
    );
    assert_eq!(
        format_business_process_flowchart_xml(&flowchart).as_bytes(),
        native
    );
}

/// A graphical-scheme font record names its optional members with a bitmask,
/// and the platform writes exactly the attributes that mask selects. Both
/// tuples below and both expected renderings are read off ERP УХ 3.2.12.6's
/// own export: mask 62 (`2+4+8+16+32`) publishes height and all four style
/// flags, and mask 46 (`2+4+8+32`) publishes the same list minus `underline`
/// -- the case that tells the mask layout apart from a fixed member order.
#[test]
fn writes_business_process_connection_line_font_from_serialized_style() {
    let case = |font: &str| {
        let style = format!(
            "{{7,{{3,0,{{0}}}},{{3,3,{{-22}}}},{{3,3,{{-3}}}},{font},{{1,0}},1,1,1,1,0,0,0,0}}"
        );
        let line = "{4,0,{0},1,1,0,e45c0cd8-a878-4bcb-8e1a-af934481e1cc,0}";
        let head = "{4,2,{1,0},\"Line\",2}";
        let geometry = format!("{{{style},6,2,50,60,70,80,{line},0,4,2,0,0,1}}");
        let item = format!("{{{head},3,-1,0,-1,0,{{{geometry}}}}}");
        let text = format!(
            "{{5,{{{{1,{{3,3,{{-10}}}},1,20,20,3,6,6,{{\"N\",10}},7,{{\"N\",10}},8,{{\"N\",10}},9,{{\"N\",10}},13,{{\"N\",0}},16,{{\"N\",0}}}}}},1,1,{item},2}}"
        );
        let flowchart = parse_business_process_flowchart_text(&text, &BTreeMap::new()).unwrap();
        let xml = format_business_process_flowchart_xml(&flowchart);
        xml.split(r#"<ConnectionLine id="2">"#)
            .nth(1)
            .unwrap()
            .split("</ConnectionLine>")
            .next()
            .unwrap()
            .split("<Font")
            .nth(1)
            .unwrap()
            .split("/>")
            .next()
            .unwrap()
            .to_string()
    };

    assert_eq!(
        case("{7,2,62,{-31},80,700,0,0,0,1,100}"),
        r#" ref="style:NormalTextFont" height="8" bold="true" italic="false" underline="false" strikeout="false" kind="StyleItem""#
    );
    assert_eq!(
        case("{7,1,46,{0},100,400,0,0,1,100}"),
        r#" xmlns:sys="http://v8.1c.ru/8.1/data/ui/fonts/system" ref="sys:DefaultGUIFont" height="10" bold="false" italic="false" strikeout="false" kind="WindowsFont""#
    );
}

#[test]
fn parses_business_process_flowchart_processing_split_and_join_items() {
    let style = "{7,{3,4,{0}},{3,3,{-22}},{3,3,{-3}},{7,1,0,{0},1,100},{1,0},1,1,1,0,0,0,0,0}";
    let processing_uuid = "11111111-1111-4111-8111-111111111111";
    let split_uuid = "22222222-2222-4222-8222-222222222222";
    let join_uuid = "33333333-3333-4333-8333-333333333333";
    let processing_head = format!("{{{{4,10,{{1,0}},\"Processing\",1}},4,{processing_uuid},0}}");
    let split_head = format!("{{{{4,20,{{1,0}},\"Split\",2}},4,{split_uuid},0}}");
    let join_head = format!("{{{{4,30,{{1,0}},\"Join\",3}},4,{join_uuid},0}}");
    let picture = "{4,0,{0},\"\",-1,-1,1,0,\"\"}";
    let border = "{4,0,{0},1,1,0,e45c0cd8-a878-4bcb-8e1a-af934481e1cc,0}";
    let shape = format!(
        "{{{{{{{style},5,10,20,50,60,4,10,20,49,20,49,59,10,59,4,{picture},{border}}},1}}}}"
    );
    let processing_item = format!("{{{processing_head},0,{shape},{{1,{{0,\"OnProcess\"}}}}}}");
    let split_item = format!("{{{split_head},1,{shape}}}");
    let join_item = format!("{{{join_head},1,{shape}}}");
    let text = format!(
        "{{5,{{{{1,{{3,3,{{-10}}}},1,20,20,3,6,6,{{\"N\",10}},7,{{\"N\",10}},8,{{\"N\",10}},9,{{\"N\",10}},13,{{\"N\",0}},16,{{\"N\",0}}}}}},3,9,{processing_item},7,{split_item},8,{join_item},31}}"
    );

    let flowchart = parse_business_process_flowchart_text(&text, &BTreeMap::new()).unwrap();

    assert_eq!(flowchart.items[0].tag, "Processing");
    assert_eq!(
        flowchart.items[0].events[0].handler.as_deref(),
        Some("OnProcess")
    );
    assert_eq!(flowchart.items[1].tag, "Split");
    assert_eq!(flowchart.items[2].tag, "Join");
}

fn subsystem_source_for_test(
    subsystem_uuid: &str,
    name: &str,
    synonym: &str,
    include_in_command_interface: bool,
    include_help_in_contents: bool,
    use_one_command: bool,
    child_uuids: &[&str],
) -> String {
    let include_in_command_interface = if include_in_command_interface { 1 } else { 0 };
    let include_help_in_contents = if include_help_in_contents { 1 } else { 0 };
    let use_one_command = if use_one_command { 1 } else { 0 };
    let children = child_uuids
        .iter()
        .map(|uuid| format!(",{uuid}"))
        .collect::<String>();
    format!(
        "{{1,\r\n{{22,\r\n{{3,\r\n{{1,0,{subsystem_uuid}}},\"{name}\",{{1,\"en\",\"{synonym}\"}},\"\"}},\r\n{include_help_in_contents},0,{include_in_command_interface},{{4,0,{{0}},0,0,0,0}},{{0}},{{0}},{use_one_command}}},0,{{00000000-0000-0000-0000-000000000000,{}{children}}}}}",
        child_uuids.len(),
    )
}

#[test]
fn writes_nested_subsystem_metadata_and_help_to_source_layout() {
    let root = std::env::temp_dir().join(format!(
        "ibcmd-rs-mssql-dump-test-{}",
        uuid::Uuid::new_v4().hyphenated()
    ));
    let _scratch = crate::test_scratch::TestScratch::adopt(&root);
    fs::create_dir_all(&root).unwrap();
    let parent_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let child_uuid = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let parent_metadata = deflate_for_test(
        subsystem_source_for_test(
            parent_uuid,
            "StandardSubsystems",
            "Standard subsystems",
            true,
            false,
            false,
            &[child_uuid],
        )
        .as_bytes(),
    );
    let child_metadata = deflate_for_test(
        subsystem_source_for_test(child_uuid, "Users", "Users", true, false, false, &[]).as_bytes(),
    );
    let help = deflate_for_test(b"{5,1,\"ru\",{#base64:PGgxPlVzZXJzPC9oMT4=},0}");
    let rows = vec![
        ConfigRow {
            file_name: parent_uuid.to_string(),
            part_no: 0,
            data_size: parent_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&parent_metadata),
        },
        ConfigRow {
            file_name: child_uuid.to_string(),
            part_no: 0,
            data_size: child_metadata.len() as i64,
            binary_hex: encode_hex_for_test(&child_metadata),
        },
        ConfigRow {
            file_name: format!("{child_uuid}.0"),
            part_no: 0,
            data_size: help.len() as i64,
            binary_hex: encode_hex_for_test(&help),
        },
    ];

    let dumped = dump_table_rows(&root, "Config", rows, false, false, true).unwrap();

    assert_eq!(dumped.metadata_xml_rows, 2);
    assert_eq!(dumped.source_asset_rows, 1);
    assert!(root.join("Subsystems/StandardSubsystems.xml").exists());
    assert!(
        root.join("Subsystems/StandardSubsystems/Subsystems/Users.xml")
            .exists()
    );
    let parent_xml = fs::read_to_string(root.join("Subsystems/StandardSubsystems.xml")).unwrap();
    assert!(
        parent_xml.contains("<Subsystem>Users</Subsystem>"),
        "{parent_xml}"
    );
    assert!(
        fs::read_to_string(
            root.join("Subsystems/StandardSubsystems/Subsystems/Users/Ext/Help.xml")
        )
        .unwrap()
        .contains("<Page>ru</Page>")
    );
    assert_eq!(
        fs::read(root.join("Subsystems/StandardSubsystems/Subsystems/Users/Ext/Help/ru.html"))
            .unwrap(),
        b"<h1>Users</h1>"
    );
    let child_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == child_uuid)
        .unwrap();
    assert_eq!(
        child_row.metadata_xml_path.as_deref(),
        Some("Subsystems/StandardSubsystems/Subsystems/Users.xml")
    );
    let help_row = dumped
        .rows
        .iter()
        .find(|row| row.file_name == format!("{child_uuid}.0"))
        .unwrap();
    assert_eq!(
        help_row.source_asset_path.as_deref(),
        Some("Subsystems/StandardSubsystems/Subsystems/Users/Ext/Help.xml")
    );
}

#[test]
fn disambiguates_colliding_metadata_object_codes() {
    let enum_uuid = "11111111-1111-4111-8111-111111111111";
    let enum_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{20,aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa,bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb,cccccccc-cccc-4ccc-cccc-cccccccccccc,dddddddd-dddd-4ddd-dddd-dddddddddddd,\r\n{{0,\r\n{{3,\r\n{{1,0,{enum_uuid}}},\"Status\",{{1,\"en\",\"Status\"}},\"\"}}\r\n}},0}}\r\n}}"
            )
            .as_bytes(),
        );
    let report_uuid = "22222222-2222-4222-8222-222222222222";
    let report_blob = deflate_for_test(
        format!(
            "{{1,\r\n{{20,aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa,bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb,\r\n{{0,\r\n{{3,\r\n{{1,0,{report_uuid}}},\"SalesReport\",{{1,\"en\",\"Sales report\"}},\"\"}}\r\n}},0}}\r\n}}"
        )
        .as_bytes(),
    );
    let subsystem_uuid = "33333333-3333-4333-8333-333333333333";
    // The old fixture was a 3-field flat shape (`{22, header, "1"}`), well
    // short of what `parse_subsystem_properties_from_text` requires (it
    // reads `fields[2]`, `fields[4]`, `fields[5]` via
    // `parse_command_group_picture_value`, `fields[6]`, `fields[7]`,
    // `fields[8]`) — the whole subsystem failed to parse. Rebuilt on the
    // already-proven `subsystem_source_for_test` builder (used by
    // `extracts_subsystem_include_in_command_interface_to_metadata_xml` and
    // friends).
    let subsystem_blob = deflate_for_test(
        subsystem_source_for_test(subsystem_uuid, "Sales", "Sales", true, false, false, &[])
            .as_bytes(),
    );
    let accounting_uuid = "44444444-4444-4444-8444-444444444444";
    let accounting_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{22,22,aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa,bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb,cccccccc-cccc-4ccc-cccc-cccccccccccc,dddddddd-dddd-4ddd-dddd-dddddddddddd,eeeeeeee-eeee-4eee-eeee-eeeeeeeeeeee,ffffffff-ffff-4fff-ffff-ffffffffffff,11111111-1111-4111-8111-111111111111,22222222-2222-4222-8222-222222222222,33333333-3333-4333-8333-333333333333,44444444-4444-4444-8444-444444444444,55555555-5555-4555-8555-555555555555,66666666-6666-4666-8666-666666666666,77777777-7777-4777-8777-777777777777,\r\n{{0,\r\n{{3,\r\n{{1,0,{accounting_uuid}}},\"Ledger\",{{1,\"en\",\"Ledger\"}},\"\"}}\r\n}},1}}\r\n}}"
            )
            .as_bytes(),
        );
    // `parse_task_properties_from_text` (`src/mssql_dump/mod.rs`) is the
    // strict owner-graph-style decoder used for Task metadata: it requires
    // an exact 9-field root and a 52-field `fields` owner block (5 marked
    // root collections, generated types, addressing attributes, etc). The
    // old fixture was a 3-field flat shape, nowhere close — no amount of
    // "field count correction" makes a hand-rolled fixture practical here,
    // so this uses the real evidence-backed corpus fixture already proven
    // by `extracts_task_child_form_ref_from_current_index` /
    // `extracts_task_generated_types_to_platform_proven_metadata_xml`
    // instead of hand-crafting one.
    let task_uuid = "32838304-a94f-4eb0-b1a6-4e5e855f022c";
    let task_text = include_str!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/task-basic/raw/32838304-a94f-4eb0-b1a6-4e5e855f022c.txt"
    );
    let task_blob = deflate_for_test(task_text.as_bytes());

    assert_eq!(
        extract_metadata_source_xml(
            &enum_blob,
            enum_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap()
        .relative_path,
        PathBuf::from("Enums").join("Status.xml")
    );
    assert_eq!(
        extract_metadata_source_xml(
            &report_blob,
            report_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap()
        .relative_path,
        PathBuf::from("Reports").join("SalesReport.xml")
    );
    assert_eq!(
        extract_metadata_source_xml(
            &subsystem_blob,
            subsystem_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap()
        .relative_path,
        PathBuf::from("Subsystems").join("Sales.xml")
    );
    assert_eq!(
        extract_metadata_source_xml(
            &accounting_blob,
            accounting_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap()
        .relative_path,
        PathBuf::from("AccountingRegisters").join("Ledger.xml")
    );
    assert_eq!(
        extract_metadata_source_xml(
            &task_blob,
            task_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap()
        .relative_path,
        PathBuf::from("Tasks").join("CorpusTask.xml")
    );

    // Catalog goes through the strict `OwnerGraphFamily` decoder
    // (`metadata_owner_graph.rs`), which needs the full 5-collection,
    // ~61-field owner root — the old flat/positional fixture here predates
    // that refactor. Rebuilt on the already-proven
    // `exact_catalog_owner_fixture_for_test` +
    // `render_owner_graph_fixture_for_test` pair (Clusters 1-3).
    let catalog_uuid = "66666666-6666-4666-8666-666666666666";
    let (_header, fields, collections) =
        exact_catalog_owner_fixture_for_test(catalog_uuid, "Products", "");
    let catalog_raw = render_owner_graph_fixture_for_test(&fields, &collections);
    let catalog_blob = deflate_for_test(catalog_raw.as_bytes());
    assert_eq!(
        extract_metadata_source_xml(
            &catalog_blob,
            catalog_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
        )
        .unwrap()
        .relative_path,
        PathBuf::from("Catalogs").join("Products.xml")
    );
}

#[test]
fn extracts_subsystem_include_in_command_interface_to_metadata_xml() {
    let true_uuid = "11111111-1111-4111-8111-111111111111";
    let true_source =
        subsystem_source_for_test(true_uuid, "Admin", "Admin", true, false, false, &[]).replacen(
            "\"\"",
            "\"subsystem comment\"",
            1,
        );
    let true_blob = deflate_for_test(true_source.as_bytes());
    let false_uuid = "22222222-2222-4222-8222-222222222222";
    let false_blob = deflate_for_test(
        subsystem_source_for_test(false_uuid, "Hidden", "Hidden", false, false, false, &[])
            .as_bytes(),
    );

    let extracted = extract_metadata_source_xml(
        &true_blob,
        true_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();

    assert_eq!(
        extracted.relative_path,
        PathBuf::from("Subsystems/Admin.xml")
    );
    assert!(xml.starts_with("\u{feff}<?xml version=\"1.0\" encoding=\"UTF-8\"?>"));
    assert!(xml.contains(r#"version="2.20""#));
    assert!(xml.contains("<Comment>subsystem comment</Comment>"));
    assert!(xml.contains("<IncludeHelpInContents>false</IncludeHelpInContents>"));
    assert!(xml.contains("<IncludeInCommandInterface>true</IncludeInCommandInterface>"));
    assert!(xml.contains("<UseOneCommand>false</UseOneCommand>"));
    assert!(
        xml.find("<Comment>subsystem comment</Comment>").unwrap()
            < xml
                .find("<IncludeHelpInContents>false</IncludeHelpInContents>")
                .unwrap()
    );
    assert!(
        xml.find("<IncludeHelpInContents>false</IncludeHelpInContents>")
            .unwrap()
            < xml
                .find("<IncludeInCommandInterface>true</IncludeInCommandInterface>")
                .unwrap()
    );

    let extracted = extract_metadata_source_xml(
        &false_blob,
        false_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();

    assert_eq!(
        extracted.relative_path,
        PathBuf::from("Subsystems/Hidden.xml")
    );
    assert!(xml.contains("<IncludeInCommandInterface>false</IncludeInCommandInterface>"));
}

#[test]
fn extracts_subsystem_native_scalar_tail_to_metadata_xml() {
    let subsystem_uuid = "11111111-1111-4111-8111-111111111111";
    let blob = deflate_for_test(
        subsystem_source_for_test(subsystem_uuid, "Admin", "Admin", false, true, true, &[])
            .as_bytes(),
    );

    for source_version in [
        InfobaseConfigSourceVersion::V2_20,
        InfobaseConfigSourceVersion::V2_21,
    ] {
        let extracted = extract_metadata_source_xml_with_refs(
            &blob,
            subsystem_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            source_version,
        )
        .unwrap();
        let xml = String::from_utf8(extracted.xml).unwrap();

        assert_eq!(
            extracted.relative_path,
            PathBuf::from("Subsystems/Admin.xml")
        );
        assert!(xml.contains(&format!(r#"version="{}""#, source_version.as_str())));
        assert!(xml.contains("<IncludeHelpInContents>true</IncludeHelpInContents>"));
        assert!(xml.contains("<IncludeInCommandInterface>false</IncludeInCommandInterface>"));
        assert!(xml.contains("<UseOneCommand>true</UseOneCommand>"));
        assert!(!xml.contains("<UseStandardCommands>"));
        assert!(
            xml.find("<Comment/>").unwrap()
                < xml
                    .find("<IncludeHelpInContents>true</IncludeHelpInContents>")
                    .unwrap()
        );
        assert!(
            xml.find("<IncludeHelpInContents>true</IncludeHelpInContents>")
                .unwrap()
                < xml
                    .find("<IncludeInCommandInterface>false</IncludeInCommandInterface>")
                    .unwrap()
        );
        assert!(
            xml.find("<IncludeInCommandInterface>false</IncludeInCommandInterface>")
                .unwrap()
                < xml.find("<UseOneCommand>true</UseOneCommand>").unwrap()
        );
    }
}

#[test]
fn extracts_subsystem_child_objects_to_metadata_xml() {
    let parent_uuid = "11111111-1111-4111-8111-111111111111";
    let child_uuid = "22222222-2222-4222-8222-222222222222";
    let source = subsystem_source_for_test(
        parent_uuid,
        "Parent",
        "Parent",
        true,
        false,
        false,
        &[child_uuid],
    );
    let blob = deflate_for_test(source.as_bytes());
    let subsystem_refs = BTreeMap::from([(
        child_uuid.to_string(),
        SubsystemSourceReference {
            relative_path: PathBuf::from("Subsystems/Parent/Subsystems/Child.xml"),
        },
    )]);

    let extracted = extract_metadata_source_xml_with_refs(
        &blob,
        parent_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &subsystem_refs,
        InfobaseConfigSourceVersion::V2_21,
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();

    assert_eq!(
        extracted.relative_path,
        PathBuf::from("Subsystems/Parent.xml")
    );
    assert!(xml.contains(r#"version="2.21""#));
    assert!(xml.contains("<ChildObjects>"));
    // `ChildObjects` lists child object names, not qualified references:
    // 1C:УТ 11.5.27.75 writes `<Subsystem>Child</Subsystem>` here.
    assert!(xml.contains("<Subsystem>Child</Subsystem>"), "{xml}");
    assert!(!xml.contains("<Subsystem>Subsystem.Parent.Subsystem.Child</Subsystem>"));
    assert!(xml.find("\t\t</Properties>").unwrap() < xml.find("<ChildObjects>").unwrap());
}

