#[test]
fn validates_platform_proven_task_assignee_native_shape() {
    let task_uuid = "3ad08f4a-6202-4099-b6cc-bc116e6731a0";
    let packed = include_bytes!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/task-assignee/raw/3ad08f4a-6202-4099-b6cc-bc116e6731a0.deflate"
    );
    let task_text = include_str!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/task-assignee/raw/3ad08f4a-6202-4099-b6cc-bc116e6731a0.txt"
    );
    assert_eq!(
        format!("{:x}", Sha256::digest(packed)),
        "2543bb3496f76cf5f6e32699a07aa1cfb3d2024a5513e0064eec0c1cffeb5ebf"
    );
    assert_eq!(
        format!("{:x}", Sha256::digest(task_text.as_bytes())),
        "eda15b8f06cdc119a180e257214d77350fd54a940a97a411aff5486583f3e22c"
    );
    assert_eq!(
        inflate_raw_deflate(packed).expect("native Task raw-deflate payload"),
        task_text.as_bytes()
    );

    let root = split_information_register_braced_fields(task_text.trim_start_matches('\u{feff}'))
        .expect("native Task root");
    assert_eq!(root.len(), 9);
    assert_eq!(root[0].trim(), "1");
    assert_eq!(root[2].trim(), "6");
    let fields = split_information_register_braced_fields(root[1]).expect("native Task fields");
    assert_eq!(fields.len(), 52);
    assert_eq!(fields[0].trim(), "33");
    assert_eq!(metadata_header_field_index(&fields, task_uuid), Some(1));
    assert_eq!(
        parse_task_generated_types(&fields, "ЗадачаИсполнителя")
            .unwrap()
            .len(),
        5
    );

    let collections = root[3..]
        .iter()
        .map(|value| parse_task_root_collection(value).expect("native Task collection"))
        .collect::<Vec<_>>();
    assert_eq!(
        collections
            .iter()
            .map(|collection| collection.marker.as_str())
            .collect::<Vec<_>>(),
        vec![
            "3daea016-69b7-4ed4-9453-127911372fe6",
            "3f58cbfb-4172-4e54-be49-561a579bb38b",
            "8ddfb495-c5fc-46b9-bdc5-bcf58341bff0",
            "e97c0570-251c-4566-b0f1-10686820f143",
            "ee865d4b-a458-48a0-b38f-5a26898feeb0",
            "f27c2152-a2c9-4c30-adb1-130f5eb2590f",
        ]
    );
    assert_eq!(
        collections
            .iter()
            .map(|collection| collection.items.len())
            .collect::<Vec<_>>(),
        vec![0, 8, 14, 4, 0, 4]
    );
    let internal_slots =
        decode_task_internal_uuid_slots(&fields).expect("native Task internal UUID slots");
    assert!(internal_slots.field_13.is_none());
    assert!(internal_slots.field_14.is_none());

    let native_xml = include_bytes!(
        "../../tests/fixtures/native-evidence/8.3.27.2214/task-assignee/native/Tasks/ЗадачаИсполнителя.xml"
    );
    assert_eq!(
        format!("{:x}", Sha256::digest(native_xml)),
        "ba812fa6ec6d63d8339775dd399a280479a973d3ecf00492c42fdb1dd20c1b05"
    );
    let native_xml = std::str::from_utf8(native_xml).expect("native Task XML is UTF-8");
    assert!(native_xml.contains(r#"<Task uuid="3ad08f4a-6202-4099-b6cc-bc116e6731a0">"#));
    assert_eq!(native_xml.matches("\t\t\t<Form>").count(), 8);
    assert_eq!(native_xml.matches("\t\t\t<Attribute uuid=").count(), 14);
    assert_eq!(
        native_xml
            .matches("\t\t\t<AddressingAttribute uuid=")
            .count(),
        4
    );
    assert_eq!(native_xml.matches("\t\t\t<Command uuid=").count(), 4);
    assert!(!native_xml.contains("\t\t\t<Template>"));
}

#[test]
fn parses_legacy_v16_data_processor_header() {
    let id = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let nil = "00000000-0000-0000-0000-000000000000";
    let text = format!(
        "{{1,{{16,{nil},{nil},{{0,{{1,{{0,0,{id}}},\"Legacy\",{{0}},\"\",0,0}}}},{nil},1,0,{nil},{nil},{nil},{{0}},{{0}}}},0}}"
    );
    let empty = BTreeMap::new();
    assert_eq!(
        metadata_source_for_text(16, &text, id),
        Some(("DataProcessor", "DataProcessors"))
    );
    let properties = parse_data_processor_properties_from_text(
        &text,
        id,
        &empty,
        &BTreeSet::new(),
        &empty,
        &empty,
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .expect("legacy data processor header");
    assert!(properties.use_standard_commands);
    assert!(!properties.include_help_in_contents);
    assert!(properties.default_form.is_none());
    let extracted = extract_metadata_source_xml_with_refs(
        &deflate_for_test(text.as_bytes()),
        id,
        &empty,
        &empty,
        &empty,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_20,
    )
    .expect("legacy data processor export");
    assert_eq!(
        extracted.relative_path,
        PathBuf::from("DataProcessors/Legacy.xml")
    );
}

#[test]
fn extracts_data_processor_generated_type_and_default_forms_to_metadata_xml() {
    let data_processor_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let default_form_uuid = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
    let auxiliary_form_uuid = "cccccccc-cccc-4ccc-8ccc-cccccccccccc";
    let object_type_id = "33333333-3333-4333-8333-333333333333";
    let object_value_id = "44444444-4444-4444-8444-444444444444";
    let manager_type_id = "11111111-1111-4111-8111-111111111111";
    let manager_value_id = "22222222-2222-4222-8222-222222222222";
    let data_processor_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{17,{object_type_id},{object_value_id},\r\n{{0,\r\n{{3,\r\n{{1,0,{data_processor_uuid}}},\"Loader\",{{1,\"en\",\"Loader\"}},\"\"}}\r\n}},{default_form_uuid},1,1,{manager_type_id},{manager_value_id},{auxiliary_form_uuid},{{1,\"en\",\"Loader extended\"}},{{1,\"en\",\"Loads data\"}}}}\r\n}}"
            )
            .as_bytes(),
        );
    let form_refs = BTreeMap::from([
        (
            default_form_uuid.to_string(),
            FormSourceReference {
                relative_path: PathBuf::from("DataProcessors/Loader/Forms/MainForm.xml"),
                kind: "Form",
            },
        ),
        (
            auxiliary_form_uuid.to_string(),
            FormSourceReference {
                relative_path: PathBuf::from("DataProcessors/Loader/Forms/AssistantForm.xml"),
                kind: "Form",
            },
        ),
    ]);

    for source_version in [
        InfobaseConfigSourceVersion::V2_20,
        InfobaseConfigSourceVersion::V2_21,
    ] {
        let extracted = extract_metadata_source_xml_with_refs(
            &data_processor_blob,
            data_processor_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &form_refs,
            &BTreeMap::new(),
            &BTreeMap::new(),
            source_version,
        )
        .unwrap();
        let xml = String::from_utf8(extracted.xml).unwrap();

        assert_eq!(
            extracted.relative_path,
            PathBuf::from("DataProcessors").join("Loader.xml")
        );
        assert!(xml.contains(&format!(r#"version="{}""#, source_version.as_str())));
        assert!(
            xml.find("<InternalInfo>").unwrap() < xml.find("<Properties>").unwrap(),
            "{xml}"
        );
        assert!(
            xml.contains(
                r#"<xr:GeneratedType name="DataProcessorObject.Loader" category="Object">"#
            ),
            "{xml}"
        );
        assert!(xml.contains(&format!("<xr:TypeId>{object_type_id}</xr:TypeId>")));
        assert!(xml.contains(&format!("<xr:ValueId>{object_value_id}</xr:ValueId>")));
        assert!(
            xml.contains(
                r#"<xr:GeneratedType name="DataProcessorManager.Loader" category="Manager">"#
            ),
            "{xml}"
        );
        assert!(xml.contains(&format!("<xr:TypeId>{manager_type_id}</xr:TypeId>")));
        assert!(xml.contains(&format!("<xr:ValueId>{manager_value_id}</xr:ValueId>")));
        assert!(xml.contains("<DefaultForm>DataProcessor.Loader.Form.MainForm</DefaultForm>"));
        assert!(
            xml.contains("<AuxiliaryForm>DataProcessor.Loader.Form.AssistantForm</AuxiliaryForm>")
        );
        assert!(xml.contains("<IncludeHelpInContents>true</IncludeHelpInContents>"));
        assert!(xml.contains("<ExtendedPresentation>"));
        assert!(xml.contains("<v8:content>Loader extended</v8:content>"));
        assert!(xml.contains("<Explanation>"));
        assert!(xml.contains("<v8:content>Loads data</v8:content>"));
        assert!(
            xml.find("<AuxiliaryForm>").unwrap() < xml.find("<IncludeHelpInContents>").unwrap(),
            "{xml}"
        );
        assert!(
            xml.find("<IncludeHelpInContents>").unwrap()
                < xml.find("<ExtendedPresentation>").unwrap(),
            "{xml}"
        );
    }
}

#[test]
fn extracts_data_processor_use_standard_commands_to_metadata_xml() {
    let data_processor_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let manager_type_id = "11111111-1111-4111-8111-111111111111";
    let manager_value_id = "22222222-2222-4222-8222-222222222222";
    let data_processor_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{17,33333333-3333-4333-8333-333333333333,44444444-4444-4444-8444-444444444444,\r\n{{0,\r\n{{3,\r\n{{1,0,{data_processor_uuid}}},\"Loader\",{{1,\"en\",\"Loader\"}},\"\"}}\r\n}},00000000-0000-0000-0000-000000000000,0,0,{manager_type_id},{manager_value_id},00000000-0000-0000-0000-000000000000,{{0}},{{0}}}}\r\n}}"
            )
            .as_bytes(),
        );

    for source_version in [
        InfobaseConfigSourceVersion::V2_20,
        InfobaseConfigSourceVersion::V2_21,
    ] {
        let extracted = extract_metadata_source_xml_with_refs(
            &data_processor_blob,
            data_processor_uuid,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            &BTreeMap::new(),
            source_version,
        )
        .unwrap();
        let xml = String::from_utf8(extracted.xml).unwrap();

        assert!(xml.contains(&format!(r#"version="{}""#, source_version.as_str())));
        assert!(xml.contains("<UseStandardCommands>false</UseStandardCommands>"));
        assert!(
            xml.find("<Comment/>").unwrap() < xml.find("<UseStandardCommands>").unwrap(),
            "{xml}"
        );
        assert!(
            xml.find("<UseStandardCommands>").unwrap() < xml.find("</Properties>").unwrap(),
            "{xml}"
        );
    }
}

