#[test]
fn catalog_nonempty_paths_and_typed_values_resolve_fail_closed() {
    let direct_uuid = "11111111-1111-4111-8111-111111111111";
    let tabular_uuid = "22222222-2222-4222-8222-222222222222";
    let nested_uuid = "33333333-3333-4333-8333-333333333333";
    let foreign_uuid = "44444444-4444-4444-8444-444444444444";
    let object_refs = BTreeMap::from([
        (
            direct_uuid.to_string(),
            "Catalog.Products.Attribute.Owner".to_string(),
        ),
        (
            tabular_uuid.to_string(),
            "Catalog.Products.TabularSection.Lines".to_string(),
        ),
        (
            nested_uuid.to_string(),
            "Catalog.Products.TabularSection.Lines.Attribute.Owner".to_string(),
        ),
        (
            foreign_uuid.to_string(),
            "Catalog.Other.Attribute.Owner".to_string(),
        ),
    ]);

    let direct = format!("{{5006,2,\"Direct\",1,{{0,{direct_uuid}}},0,\"Ref\",1,{{-8}},1}}");
    let direct_links =
        parse_catalog_choice_parameter_links(&direct, "Products", false, &object_refs).unwrap();
    assert_eq!(direct_links.len(), 2);
    assert_eq!(
        direct_links[0].data_path,
        "Catalog.Products.Attribute.Owner"
    );
    assert_eq!(direct_links[0].value_change, "Clear");
    assert_eq!(
        direct_links[1].data_path,
        "Catalog.Products.StandardAttribute.Ref"
    );
    assert_eq!(direct_links[1].value_change, "DontChange");

    let nested_direct = format!("{{5006,1,\"Direct\",1,{{0,{direct_uuid}}},0}}");
    assert!(
        parse_catalog_choice_parameter_links(&nested_direct, "Products", true, &object_refs)
            .is_some()
    );
    let nested_path = format!("{{5006,1,\"Nested\",2,{{0,{tabular_uuid}}},{{0,{nested_uuid}}},1}}");
    let nested_links =
        parse_catalog_choice_parameter_links(&nested_path, "Products", true, &object_refs).unwrap();
    assert_eq!(
        nested_links[0].data_path,
        "Catalog.Products.TabularSection.Lines.Attribute.Owner"
    );
    assert_eq!(nested_links[0].value_change, "DontChange");
    let path3 = format!(
        "{{5006,1,\"Nested\",3,{{0,{tabular_uuid}}},{{0,{nested_uuid}}},{{0,{nested_uuid}}},0}}"
    );
    assert!(parse_catalog_choice_parameter_links(&path3, "Products", true, &object_refs).is_none());
    // A reference that leaves the owner is written back as the raw `0:<uuid>`
    // the record carries: that is what the platform writes for every one of
    // the 61 such links on the stand.
    let foreign = format!("{{5006,1,\"Foreign\",1,{{0,{foreign_uuid}}},0}}");
    let foreign_links =
        parse_catalog_choice_parameter_links(&foreign, "Products", false, &object_refs).unwrap();
    assert_eq!(foreign_links[0].data_path, format!("0:{foreign_uuid}"));
    let wrong_count = format!("{{5006,2,\"Direct\",1,{{0,{direct_uuid}}},0}}");
    assert!(
        parse_catalog_choice_parameter_links(&wrong_count, "Products", false, &object_refs)
            .is_none()
    );

    let link_by_type = format!("{{3,1,{{0,{direct_uuid}}},3}}");
    let (empty, link) =
        parse_catalog_link_by_type(&link_by_type, "Products", &object_refs).unwrap();
    assert!(!empty);
    let link = link.unwrap();
    assert_eq!(link.data_path, "Catalog.Products.Attribute.Owner");
    assert_eq!(link.link_item, 3);
    let foreign_link = format!("{{3,1,{{0,{foreign_uuid}}},0}}");
    let (_, foreign_link) =
        parse_catalog_link_by_type(&foreign_link, "Products", &object_refs).unwrap();
    assert_eq!(foreign_link.unwrap().data_path, format!("0:{foreign_uuid}"));

    let values = parse_information_register_choice_parameters(
        r#"{0,2,"Amount",{"N",-12.50},"Moment",{"D",20240203040506}}"#,
        &BTreeMap::new(),
        &BTreeMap::new(),
    )
    .unwrap();
    assert!(matches!(
        &values[0].value,
        MetadataChoiceParameterValue::Decimal(value) if value == "-12.50"
    ));
    assert!(matches!(
        &values[1].value,
        MetadataChoiceParameterValue::DateTime(value) if value == "2024-02-03T04:05:06"
    ));
}

#[test]
fn catalog_choice_form_accepts_any_resolved_form_reference() {
    let form_uuid = "11111111-1111-4111-8111-111111111111";
    let owner_uuid = "22222222-2222-4222-8222-222222222222";
    let form_refs = BTreeMap::from([(
        form_uuid.to_string(),
        FormSourceReference {
            relative_path: PathBuf::from("Catalogs/Statuses/Forms/Choice.xml"),
            kind: "Form",
        },
    )]);
    // The matrix proves the platform accepts a document form on a string
    // catalog attribute, so no reference-type owner check is applied.
    assert!(matches!(
        parse_catalog_child_choice_form(form_uuid, &form_refs),
        Some(MetadataChoiceForm::Reference(reference))
            if reference == "Catalog.Statuses.Form.Choice"
    ));
    let typed = format!("{{\"#\",{DESIGN_TIME_REF_TYPE_UUID},{{0,{owner_uuid},{form_uuid}}}}}");
    assert!(parse_catalog_child_choice_form(&typed, &form_refs).is_none());
}

#[test]
fn formats_every_metadata_choice_parameter_value_variant() {
    let parameters = vec![
        MetadataChoiceParameter {
            name: "Nil".to_string(),
            value: MetadataChoiceParameterValue::Nil,
        },
        MetadataChoiceParameter {
            name: "Boolean".to_string(),
            value: MetadataChoiceParameterValue::Boolean(true),
        },
        MetadataChoiceParameter {
            name: "Decimal".to_string(),
            value: MetadataChoiceParameterValue::Decimal("-12.50".to_string()),
        },
        MetadataChoiceParameter {
            name: "DateTime".to_string(),
            value: MetadataChoiceParameterValue::DateTime("2024-02-03T04:05:06".to_string()),
        },
        MetadataChoiceParameter {
            name: "String".to_string(),
            value: MetadataChoiceParameterValue::String("a<&b".to_string()),
        },
        MetadataChoiceParameter {
            name: "EmptyRef".to_string(),
            value: MetadataChoiceParameterValue::DesignTimeRef(String::new()),
        },
        MetadataChoiceParameter {
            name: "Ref".to_string(),
            value: MetadataChoiceParameterValue::DesignTimeRef("Catalog.Statuses.Open".to_string()),
        },
        MetadataChoiceParameter {
            name: "EmptyArray".to_string(),
            value: MetadataChoiceParameterValue::FixedArray(Vec::new()),
        },
        MetadataChoiceParameter {
            name: "Array".to_string(),
            value: MetadataChoiceParameterValue::FixedArray(vec![
                MetadataChoiceParameterValue::DesignTimeRef("Catalog.Statuses.Open".to_string()),
                MetadataChoiceParameterValue::DesignTimeRef(String::new()),
            ]),
        },
    ];
    let mut xml = String::new();
    push_metadata_child_choice_parameters_xml(&mut xml, "\t", &parameters);

    assert!(xml.contains(r#"<app:value xsi:nil="true"/>"#));
    assert!(xml.contains(r#"<app:value xsi:type="xs:boolean">true</app:value>"#));
    assert!(xml.contains(r#"<app:value xsi:type="xs:decimal">-12.50</app:value>"#));
    assert!(xml.contains(r#"<app:value xsi:type="xs:dateTime">2024-02-03T04:05:06</app:value>"#));
    assert!(xml.contains(r#"<app:value xsi:type="xs:string">a&lt;&amp;b</app:value>"#));
    assert!(xml.contains(r#"<app:value xsi:type="xr:DesignTimeRef"/>"#));
    assert!(
        xml.contains(r#"<app:value xsi:type="xr:DesignTimeRef">Catalog.Statuses.Open</app:value>"#)
    );
    assert!(xml.contains(r#"<app:value xsi:type="v8:FixedArray"/>"#));
    assert!(
        xml.contains(r#"<v8:Value xsi:type="xr:DesignTimeRef">Catalog.Statuses.Open</v8:Value>"#)
    );
    assert!(xml.contains(r#"<v8:Value xsi:type="xr:DesignTimeRef"></v8:Value>"#));

    let mut document_xml = String::new();
    push_metadata_child_choice_parameters_xml_with_style(
        &mut document_xml,
        "\t",
        &parameters,
        true,
    );
    assert!(document_xml.contains(r#"<v8:Value xsi:type="xr:DesignTimeRef"/>"#));
    assert!(!document_xml.contains(r#"<v8:Value xsi:type="xr:DesignTimeRef"></v8:Value>"#));
}

#[test]
fn extracts_catalog_child_attribute_property_tail_and_choice_parameters() {
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let attribute_uuid = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
    let status_uuid = "cccccccc-cccc-4ccc-8ccc-ccccccccccc1";
    let choice_form_uuid = "cccccccc-cccc-4ccc-8ccc-ccccccccccc2";
    let status_owner_type_uuid = "cccccccc-cccc-4ccc-8ccc-ccccccccccc3";
    let choice_owner_type_uuid = "cccccccc-cccc-4ccc-8ccc-ccccccccccc4";
    let type_set_uuid = "cccccccc-cccc-4ccc-8ccc-ccccccccccc5";
    let zero_uuid = "00000000-0000-0000-0000-000000000000";
    let single_parameter_value = format!(
        r##"{{"#",5c14e26f-099b-4d37-84a6-b433d87400da,{{0,{status_owner_type_uuid},{status_uuid}}}}}"##
    );
    let choice_parameters = [r#"{0,1,"Filter.Status","#, &single_parameter_value, "}"].concat();
    let attribute_collection = r##"{cf4abea7-37b2-11d4-940f-008048da11f9,1,
{
{6,
{27,
{2,
{3,
{1,0,$ATTRIBUTE},"RequiredFlag",{1,"en","Required flag"},"",0,0,$ZERO,0},
{"Pattern",{"B"},{"#",$CHOICE_OWNER_TYPE},{"#",$TYPE_SET}}
},
0,{1,"en","Flag format"},{1,"en","Flag tooltip"},0,"",0,
{"U"},{"U"},0,$CHOICE_FORM,1,1,
{5006,0},
{3,0,0},
$CHOICE_PARAMETERS,
0,{0},{"B",0},0,2,0
},2,2,1,1,0,{1,$ZERO}
},0}
}"##
    .replace("$ATTRIBUTE", attribute_uuid)
    .replace("$ZERO", zero_uuid)
    .replace("$CHOICE_OWNER_TYPE", choice_owner_type_uuid)
    .replace("$TYPE_SET", type_set_uuid)
    .replace("$CHOICE_FORM", choice_form_uuid)
    .replace("$CHOICE_PARAMETERS", &choice_parameters);
    let (_header, mut fields, mut collections) =
        exact_catalog_owner_fixture_for_test(catalog_uuid, "Products", "");
    fields[1] = "11111111-1111-4111-8111-111111111111".to_owned();
    fields[2] = "11111111-1111-4111-8111-111111111112".to_owned();
    fields[3] = "22222222-2222-4222-8222-222222222221".to_owned();
    fields[4] = "22222222-2222-4222-8222-222222222222".to_owned();
    fields[5] = "33333333-3333-4333-8333-333333333331".to_owned();
    fields[6] = "33333333-3333-4333-8333-333333333332".to_owned();
    fields[7] = "44444444-4444-4444-8444-444444444441".to_owned();
    fields[8] = "44444444-4444-4444-8444-444444444442".to_owned();
    fields[34] = "55555555-5555-4555-8555-555555555551".to_owned();
    fields[35] = "55555555-5555-4555-8555-555555555552".to_owned();
    collections[3] = attribute_collection;
    let catalog_raw = render_owner_graph_fixture_for_test(&fields, &collections);
    let catalog_blob = deflate_for_test(catalog_raw.as_bytes());
    let object_refs = BTreeMap::from([
        (
            attribute_uuid.to_string(),
            "Catalog.Products.Attribute.RequiredFlag".to_string(),
        ),
        (
            status_uuid.to_string(),
            "Enum.Statuses.EnumValue.Open".to_string(),
        ),
    ]);
    let type_index = BTreeMap::from([
        (
            status_owner_type_uuid.to_string(),
            "cfg:EnumRef.Statuses".to_string(),
        ),
        (
            choice_owner_type_uuid.to_string(),
            "cfg:CatalogRef.Statuses".to_string(),
        ),
        (
            type_set_uuid.to_string(),
            "cfg:DefinedType.FilterValue".to_string(),
        ),
    ]);
    let form_refs = BTreeMap::from([(
        choice_form_uuid.to_string(),
        FormSourceReference {
            relative_path: PathBuf::from("Catalogs/Statuses/Forms/ChoiceForm.xml"),
            kind: "Form",
        },
    )]);

    let extracted = extract_metadata_source_xml_with_refs(
        &catalog_blob,
        catalog_uuid,
        &type_index,
        &object_refs,
        &BTreeMap::new(),
        &form_refs,
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_21,
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();
    let attribute_start = xml
        .find(r#"<Attribute uuid="bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb">"#)
        .unwrap();
    let attribute_end = attribute_start + xml[attribute_start..].find("</Attribute>").unwrap();
    let attribute_xml = &xml[attribute_start..attribute_end];

    assert!(
        attribute_xml.contains("<v8:Type>xs:boolean</v8:Type>"),
        "{xml}"
    );
    assert!(attribute_xml.contains("<v8:Type>cfg:CatalogRef.Statuses</v8:Type>"));
    assert!(attribute_xml.contains("<v8:TypeSet>cfg:DefinedType.FilterValue</v8:TypeSet>"));
    assert!(attribute_xml.contains("<PasswordMode>false</PasswordMode>"));
    assert!(attribute_xml.contains("<Format>"));
    assert!(attribute_xml.contains("<v8:content>Flag format</v8:content>"));
    assert!(attribute_xml.contains("<ToolTip>"));
    assert!(attribute_xml.contains("<v8:content>Flag tooltip</v8:content>"));
    assert!(attribute_xml.contains(r#"<FillValue xsi:type="xs:boolean">false</FillValue>"#));
    assert!(attribute_xml.contains("<FillChecking>ShowError</FillChecking>"));
    assert!(attribute_xml.contains("<ChoiceFoldersAndItems>Items</ChoiceFoldersAndItems>"));
    assert!(attribute_xml.contains("<ChoiceParameterLinks/>"));
    assert!(attribute_xml.contains(r#"<app:item name="Filter.Status">"#));
    assert!(attribute_xml.contains(
        r#"<app:value xsi:type="xr:DesignTimeRef">Enum.Statuses.EnumValue.Open</app:value>"#
    ));
    assert!(attribute_xml.contains("<QuickChoice>Use</QuickChoice>"));
    assert!(attribute_xml.contains("<CreateOnInput>Use</CreateOnInput>"));
    assert!(attribute_xml.contains("<ChoiceForm>Catalog.Statuses.Form.ChoiceForm</ChoiceForm>"));
    assert!(attribute_xml.contains("<LinkByType/>"));
    assert!(attribute_xml.contains("<ChoiceHistoryOnInput>Auto</ChoiceHistoryOnInput>"));
    assert!(attribute_xml.contains("<Use>ForFolderAndItem</Use>"));
    assert!(attribute_xml.contains("<Indexing>IndexWithAdditionalOrder</Indexing>"));
    assert!(attribute_xml.contains("<FullTextSearch>Use</FullTextSearch>"));
    assert!(attribute_xml.contains("<DataHistory>Use</DataHistory>"));
    assert!(!attribute_xml.contains("<UpdateDataHistoryImmediatelyAfterWrite>"));
    assert!(!attribute_xml.contains("<ExecuteAfterWriteDataHistoryVersionProcessing>"));
    let boolean_type = attribute_xml.find("<v8:Type>xs:boolean</v8:Type>").unwrap();
    let catalog_type = attribute_xml
        .find("<v8:Type>cfg:CatalogRef.Statuses</v8:Type>")
        .unwrap();
    let type_set = attribute_xml
        .find("<v8:TypeSet>cfg:DefinedType.FilterValue</v8:TypeSet>")
        .unwrap();
    let password_mode = attribute_xml.find("<PasswordMode>").unwrap();
    assert!(boolean_type < catalog_type && catalog_type < type_set && type_set < password_mode);
    assert!(
        attribute_xml.find("<FillValue").unwrap() < attribute_xml.find("<FillChecking>").unwrap(),
        "{xml}"
    );
    assert!(
        attribute_xml.find("<ChoiceParameters>").unwrap()
            < attribute_xml.find("<QuickChoice>").unwrap(),
        "{xml}"
    );
    assert!(
        attribute_xml.find("<CreateOnInput>").unwrap()
            < attribute_xml.find("<ChoiceForm>").unwrap(),
        "{xml}"
    );
    assert!(
        attribute_xml.find("<ChoiceForm>").unwrap() < attribute_xml.find("<LinkByType/>").unwrap(),
        "{xml}"
    );
    assert!(
        attribute_xml.find("<ChoiceHistoryOnInput>").unwrap()
            < attribute_xml.find("<Use>").unwrap(),
        "{xml}"
    );
}

#[test]
fn extracts_catalog_nested_tabular_section_attribute_tail_scalars() {
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let tabular_section_uuid = "cccccccc-cccc-4ccc-8ccc-cccccccccccc";
    let tabular_attribute_uuid = "dddddddd-dddd-4ddd-8ddd-dddddddddddd";
    let (_header, fields, mut collections) =
        exact_catalog_owner_fixture_for_test(catalog_uuid, "Products", "");
    let nested = catalog_attribute_wrapper_with_payload_overrides_for_test(
        8,
        tabular_attribute_uuid,
        r#"{"Pattern",{"S",20,1}}"#,
        r#"{"S",""}"#,
        "0",
        &[(12, "1"), (21, "1")],
    );
    let tabular = owner_graph_tabular_section_item_for_test(
        owner_graph::OwnerGraphFamily::Catalog,
        tabular_section_uuid,
        "Prices",
        [
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1",
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee2",
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee3",
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee4",
        ],
        &[nested],
    );
    collections[2] = format!("{{{CATALOG_TABULAR_SECTION_COLLECTION_UUID},1,{tabular}}}");
    let catalog_raw = render_owner_graph_fixture_for_test(&fields, &collections);
    let catalog_blob = deflate_for_test(catalog_raw.as_bytes());
    let object_refs = BTreeMap::from([
        (
            tabular_section_uuid.to_string(),
            "Catalog.Products.TabularSection.Prices".to_string(),
        ),
        (
            tabular_attribute_uuid.to_string(),
            "Catalog.Products.TabularSection.Prices.Attribute.Field".to_string(),
        ),
    ]);

    let extracted = extract_metadata_source_xml_with_refs(
        &catalog_blob,
        catalog_uuid,
        &BTreeMap::new(),
        &object_refs,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_20,
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();
    let tabular_start = xml
        .find(r#"<TabularSection uuid="cccccccc-cccc-4ccc-8ccc-cccccccccccc">"#)
        .unwrap();
    let tabular_end = tabular_start + xml[tabular_start..].find("</TabularSection>").unwrap();
    let tabular_xml = &xml[tabular_start..tabular_end];
    let attribute_start = tabular_xml
        .find(r#"<Attribute uuid="dddddddd-dddd-4ddd-8ddd-dddddddddddd">"#)
        .unwrap();
    let attribute_end =
        attribute_start + tabular_xml[attribute_start..].find("</Attribute>").unwrap();
    let attribute_xml = &tabular_xml[attribute_start..attribute_end];

    assert!(attribute_xml.contains("<ChoiceFoldersAndItems>Items</ChoiceFoldersAndItems>"));
    assert!(attribute_xml.contains("<QuickChoice>Use</QuickChoice>"));
    assert!(attribute_xml.contains("<CreateOnInput>DontUse</CreateOnInput>"));
    assert!(attribute_xml.contains("<ChoiceForm/>"));
    assert!(!attribute_xml.contains("<Use>"));
    assert!(attribute_xml.contains("<Indexing>IndexWithAdditionalOrder</Indexing>"));
    assert!(attribute_xml.contains("<FullTextSearch>Use</FullTextSearch>"));
    assert!(attribute_xml.contains("<DataHistory>Use</DataHistory>"));
    assert!(!attribute_xml.contains("<FillFromFillingValue>"));
    assert!(!attribute_xml.contains("<FillValue"));
    assert!(!attribute_xml.contains("<UpdateDataHistoryImmediatelyAfterWrite>"));
    assert!(!attribute_xml.contains("<ExecuteAfterWriteDataHistoryVersionProcessing>"));
    assert!(
        attribute_xml.find("<FillChecking>").unwrap()
            < attribute_xml.find("<ChoiceFoldersAndItems>").unwrap(),
        "{xml}"
    );
    assert!(
        attribute_xml.find("<ChoiceForm/>").unwrap()
            < attribute_xml.find("<ChoiceHistoryOnInput>").unwrap(),
        "{xml}"
    );
}

#[test]
fn extracts_catalog_tabular_section_property_tail() {
    let catalog_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let tabular_section_uuid = "cccccccc-cccc-4ccc-8ccc-cccccccccccc";
    let tabular_attribute_uuid = "dddddddd-dddd-4ddd-8ddd-dddddddddddd";
    let (_header, fields, mut collections) =
        exact_catalog_owner_fixture_for_test(catalog_uuid, "Products", "");
    let nested = catalog_attribute_wrapper_for_test(
        8,
        tabular_attribute_uuid,
        r#"{"Pattern",{"S",20,1}}"#,
        r#"{"S",""}"#,
        "0",
    );
    let mut line_number_values =
        information_register_standard_attribute_values_for_test("LineNumber", true);
    line_number_values[1] = information_register_standard_attribute_direct_enum_for_test(
        INFORMATION_REGISTER_STANDARD_ATTRIBUTE_FILL_CHECKING_UUID,
        "1",
    );
    line_number_values[22] = "{\"U\"}".to_string();
    let line_number_bag =
        information_register_standard_attribute_bag_from_values_for_test(&line_number_values, true);
    let standard_attributes_presence = format!(
        "{{1,{{1,1,{{-10}},{INFORMATION_REGISTER_STANDARD_ATTRIBUTE_SECTION_UUID},{line_number_bag}}}}}"
    );
    let tabular = catalog_tabular_section_item_with_overrides_for_test(
        tabular_section_uuid,
        "Prices",
        [
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee1",
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee2",
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee3",
            "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeee4",
        ],
        &[nested],
        "2",
        &[
            (6, "1"),
            (7, &standard_attributes_presence),
            (8, "{1,\"en\",\"Price rows\"}"),
        ],
    );
    collections[2] = format!("{{{CATALOG_TABULAR_SECTION_COLLECTION_UUID},1,{tabular}}}");
    let catalog_raw = render_owner_graph_fixture_for_test(&fields, &collections);
    let catalog_blob = deflate_for_test(catalog_raw.as_bytes());
    let object_refs = BTreeMap::from([
        (
            tabular_section_uuid.to_string(),
            "Catalog.Products.TabularSection.Prices".to_string(),
        ),
        (
            tabular_attribute_uuid.to_string(),
            "Catalog.Products.TabularSection.Prices.Attribute.Field".to_string(),
        ),
    ]);

    let extracted = extract_metadata_source_xml_with_refs(
        &catalog_blob,
        catalog_uuid,
        &BTreeMap::new(),
        &object_refs,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_20,
    )
    .unwrap();
    let xml = String::from_utf8(extracted.xml).unwrap();
    let tabular_start = xml
        .find(r#"<TabularSection uuid="cccccccc-cccc-4ccc-8ccc-cccccccccccc">"#)
        .unwrap();
    let tabular_end = tabular_start + xml[tabular_start..].find("</TabularSection>").unwrap();
    let tabular_xml = &xml[tabular_start..tabular_end];

    assert!(tabular_xml.contains("<ToolTip>"), "{xml}");
    assert!(tabular_xml.contains("<v8:content>Price rows</v8:content>"));
    assert!(tabular_xml.contains("<FillChecking>ShowError</FillChecking>"));
    assert!(tabular_xml.contains("<StandardAttributes>"));
    assert!(tabular_xml.contains(r#"<xr:StandardAttribute name="LineNumber">"#));
    // `line_number_fill_checking` is schema-fixed to "DontCheck" whenever a
    // presence/fill-value override is declared for LineNumber (never
    // "ShowError" - see `parse_exact_metadata_tabular_section`); its
    // presence at all (vs. the omitted element when absent) is what this
    // assertion is really exercising.
    assert!(tabular_xml.contains("<xr:FillChecking>DontCheck</xr:FillChecking>"));
    assert!(tabular_xml.contains("<Use>ForFolderAndItem</Use>"));
    assert!(tabular_xml.contains("<LineNumberLength>5</LineNumberLength>"));
    assert!(
        tabular_xml.find("<Comment/>").unwrap() < tabular_xml.find("<ToolTip>").unwrap(),
        "{xml}"
    );
    assert!(
        tabular_xml.find("<StandardAttributes>").unwrap() < tabular_xml.find("<Use>").unwrap(),
        "{xml}"
    );
    assert!(
        tabular_xml.find("<LineNumberLength>").unwrap()
            < tabular_xml.find("<ChildObjects>").unwrap(),
        "{xml}"
    );
}

#[test]
fn builds_register_and_characteristic_chart_reference_type_index_entries() {
    let info_register_uuid = "aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa";
    let record_type_id = "bbbbbbbb-bbbb-4bbb-bbbb-bbbbbbbbbbbb";
    let record_set_type_id = "cccccccc-cccc-4ccc-cccc-cccccccccccc";
    let info_register_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{33,{record_type_id},11111111-1111-4111-8111-111111111111,22222222-2222-4222-8222-222222222222,33333333-3333-4333-8333-333333333333,44444444-4444-4444-8444-444444444444,55555555-5555-4555-8555-555555555555,66666666-6666-4666-8666-666666666666,77777777-7777-4777-8777-777777777777,{record_set_type_id},88888888-8888-4888-8888-888888888888,99999999-9999-4999-8999-999999999999,aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee,ffffffff-ffff-4fff-8fff-ffffffffffff,eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee,\r\n{{0,\r\n{{3,\r\n{{1,0,{info_register_uuid}}},\"Prices\",{{1,\"en\",\"Prices\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}}\r\n}},0}}\r\n}}"
            )
            .as_bytes(),
        );
    let chart_uuid = "dddddddd-dddd-4ddd-dddd-dddddddddddd";
    let chart_object_type_id = "eeeeeeee-eeee-4eee-eeee-eeeeeeeeeeee";
    let chart_ref_type_id = "ffffffff-ffff-4fff-ffff-ffffffffffff";
    let chart_blob = deflate_for_test(
            format!(
                "{{1,\r\n{{34,{chart_object_type_id},11111111-1111-4111-8111-111111111111,{chart_ref_type_id},22222222-2222-4222-8222-222222222222,33333333-3333-4333-8333-333333333333,44444444-4444-4444-8444-444444444444,55555555-5555-4555-8555-555555555555,66666666-6666-4666-8666-666666666666,77777777-7777-4777-8777-777777777777,88888888-8888-4888-8888-888888888888,99999999-9999-4999-8999-999999999999,aaaaaaaa-bbbb-4ccc-8ddd-eeeeeeeeeeee,\r\n{{0,\r\n{{3,\r\n{{1,0,{chart_uuid}}},\"ExpenseItems\",{{1,\"en\",\"Expense items\"}},\"\",0,0,00000000-0000-0000-0000-000000000000,0}}\r\n}},0}}\r\n}}"
            )
            .as_bytes(),
        );
    let rows = vec![
        ConfigRow {
            file_name: info_register_uuid.to_string(),
            part_no: 0,
            data_size: info_register_blob.len() as i64,
            binary_hex: encode_hex_for_test(&info_register_blob),
        },
        ConfigRow {
            file_name: chart_uuid.to_string(),
            part_no: 0,
            data_size: chart_blob.len() as i64,
            binary_hex: encode_hex_for_test(&chart_blob),
        },
    ];

    let index = build_metadata_type_index(&rows);

    assert_eq!(
        index.get(record_type_id).map(String::as_str),
        Some("cfg:InformationRegisterRecord.Prices")
    );
    assert_eq!(
        index.get(record_set_type_id).map(String::as_str),
        Some("cfg:InformationRegisterRecordSet.Prices")
    );
    assert_eq!(
        index.get(chart_object_type_id).map(String::as_str),
        Some("cfg:ChartOfCharacteristicTypesObject.ExpenseItems")
    );
    assert_eq!(
        index.get(chart_ref_type_id).map(String::as_str),
        Some("cfg:ChartOfCharacteristicTypesRef.ExpenseItems")
    );
}

