        self.fields[19] = CALCULATION_SCHEDULE_TEST_UUID.to_string();
        self.fields[20] = CALCULATION_SCHEDULE_VALUE_TEST_UUID.to_string();
        self.fields[21] = CALCULATION_SCHEDULE_DATE_TEST_UUID.to_string();
