#[test]
fn characteristics_cct_preconditions_preserve_exact_zero_pair_and_binary_lexemes() {
    let mut fields = vec![""; 59];
    fields[15] = "{0,0}";
    fields[36] = "0";
    fields[52] = "{1,{0,0}}";
    assert!(cct_characteristics_preconditions(&fields));
    fields[36] = "1";
    assert!(cct_characteristics_preconditions(&fields));
    for valid in [" 0 ", "1 "] {
        fields[36] = valid;
        assert!(
            cct_characteristics_preconditions(&fields),
            "rejected baseline-compatible padded flag {valid:?}"
        );
    }

    for invalid in ["00", "01"] {
        fields[36] = invalid;
        assert!(!cct_characteristics_preconditions(&fields));
    }
    fields[36] = "0";
    for valid in ["{ 0 ,0 }", "{0, 0}"] {
        fields[15] = valid;
        assert!(
            cct_characteristics_preconditions(&fields),
            "rejected baseline-compatible padded pair {valid:?}"
        );
    }
    for invalid in ["{1,1}", "{00,0}", "{0,00}", "{0}", "{0,0,0}", "0,0", "{0,0"] {
        fields[15] = invalid;
        assert!(
            !cct_characteristics_preconditions(&fields),
            "accepted invalid pair {invalid:?}"
        );
    }
}

#[test]
fn characteristics_standard_attribute_marker_follows_the_source_family() {
    // Real bytes, ДО КОРП 3.0.21.3: one `BusinessProcess.Исполнение`
    // characteristic reads its types out of a Catalog tabular section with
    // marker `-8` and its values out of its own tabular section with marker
    // `-5`, and the platform spells both `.StandardAttribute.Ref`. Which
    // number spells `Ref` is therefore declared by the family of the object
    // the reference points at, not by the family that owns the property and
    // not by the field's role.
    let cases = [
        ("Catalog.Types.TabularSection.Rows", -8, "Ref"),
        ("Document.Values.TabularSection.Rows", -5, "Ref"),
        ("BusinessProcess.Values.TabularSection.Rows", -5, "Ref"),
        ("Task.Values.TabularSection.Rows", -5, "Ref"),
        (
            "ChartOfCharacteristicTypes.Types.TabularSection.Rows",
            -2,
            "Ref",
        ),
        ("Catalog.Values", -4, "Parent"),
        ("ChartOfCharacteristicTypes.Types", -2, "Ref"),
    ];
    for (source, marker, name) in cases {
        let reference = CharacteristicReference::new(source, None).unwrap();
        for role in [
            CharacteristicRole::ObjectField,
            CharacteristicRole::TypeField,
            CharacteristicRole::KeyField,
        ] {
            let decoded = decode_field(
                CharacteristicsOwnerFamily::Catalog,
                0,
                &field(&marker.to_string()),
                role,
                &reference,
                &BTreeMap::new(),
            )
            .unwrap_or_else(|error| panic!("{source} marker {marker} refused: {error:?}"));
            assert_eq!(
                decoded.reference().map(CharacteristicReference::path),
                Some(format!("{source}.StandardAttribute.{name}").as_str())
            );
        }
    }
    // A tabular-section source exposes only its owner's `Ref`; every other
    // entry of the family table stays closed there.
    let rows = CharacteristicReference::new("Catalog.Values.TabularSection.Rows", None).unwrap();
    let failure = decode_field(
        CharacteristicsOwnerFamily::Catalog,
        0,
        &field("-4"),
        CharacteristicRole::ObjectField,
        &rows,
        &BTreeMap::new(),
    )
    .unwrap_err();
    assert_eq!(failure.reason, CharacteristicsReason::UnsupportedMarker);
    // A family with no standard-attribute table of its own fails closed
    // instead of borrowing the owner's numbering.
    let register = CharacteristicReference::new("InformationRegister.Values", None).unwrap();
    let failure = decode_field(
        CharacteristicsOwnerFamily::Catalog,
        0,
        &field("-8"),
        CharacteristicRole::ObjectField,
        &register,
        &BTreeMap::new(),
    )
    .unwrap_err();
    assert_eq!(failure.reason, CharacteristicsReason::UnsupportedMarker);
}

#[test]
fn characteristics_filter_value_prints_the_stored_pair_when_only_the_value_dangles() {
    // Real bytes, ERP УХ 3.2.12.6 `Catalogs/КлассификаторЕдиницИзмерения`: the
    // characteristic's `<xr:TypesFilterValue>` stores a design-time reference
    // whose owner uuid is the `Ref` type id of another catalog -- so the type
    // index names it -- and whose value uuid occurs nowhere else in the whole
    // reference tree. The platform writes `<owner uuid>.<value uuid>`
    // verbatim; the reader used to refuse, costing the catalog its file.
    let owner_uuid = "7a576bbd-3683-4c69-8259-b03d2c59db04";
    let dangling_uuid = "a63118e9-972c-4c4d-99fa-7338a4fc913a";
    let known_uuid = "b0f9d9f2-9a6c-4a9b-b7b5-2d4f0c3d1e77";
    let type_index = BTreeMap::from([(owner_uuid.to_owned(), "cfg:CatalogRef.Наборы".to_owned())]);
    let filter = |value_uuid: &str| {
        format!("{{\"#\",{DESIGN_TIME_REF_TYPE_UUID},{{0,{owner_uuid},{value_uuid}}}}}")
    };
    let decode_with = |raw: &str, metadata_refs: &BTreeMap<String, String>| {
        decode_characteristics_with_owner_code(
            CharacteristicsOwnerFamily::Catalog,
            None,
            raw,
            &type_index,
            metadata_refs,
            &references(),
        )
    };
    let model = decode_with(
        &collection(&item(
            "4",
            DOCUMENT_CHARACTERISTIC_TYPE_UUID,
            &filter(dangling_uuid),
        )),
        &BTreeMap::new(),
    )
    .unwrap();
    let expected = format!("{owner_uuid}.{dangling_uuid}");
    assert!(matches!(
        model.items()[0].types().types_filter_value(),
        CharacteristicFilterValue::DesignTimeRef(Some(reference))
            if reference.path() == expected
    ));

    // A value any index names is a resolution, not a dangling reference: it is
    // resolved, never downgraded to the raw pair.
    let known = BTreeMap::from([(known_uuid.to_owned(), "Catalog.Наборы.Значение".to_owned())]);
    let model = decode_with(
        &collection(&item(
            "4",
            DOCUMENT_CHARACTERISTIC_TYPE_UUID,
            &filter(known_uuid),
        )),
        &known,
    )
    .unwrap();
    assert!(matches!(
        model.items()[0].types().types_filter_value(),
        CharacteristicFilterValue::DesignTimeRef(Some(reference))
            if reference.path() == "Catalog.Наборы.Значение"
    ));

    // And a value the TYPE index names is not dangling either -- that is an
    // incomplete resolution, which still refuses.
    let mut colliding_type_index = type_index.clone();
    colliding_type_index.insert(dangling_uuid.to_owned(), "cfg:CatalogRef.Прочее".to_owned());
    let diagnostic = decode_characteristics_with_owner_code(
        CharacteristicsOwnerFamily::Catalog,
        None,
        &collection(&item(
            "4",
            DOCUMENT_CHARACTERISTIC_TYPE_UUID,
            &filter(dangling_uuid),
        )),
        &colliding_type_index,
        &BTreeMap::new(),
        &references(),
    )
    .unwrap_err();
    assert_eq!(
        diagnostic.reason,
        CharacteristicsReason::UnsupportedFilterUnion
    );
}

#[test]
fn characteristics_filter_value_union_covers_undefined_and_boolean_members() {
    // Real bytes: `{"U"}` is the union member the platform spells
    // `<xr:TypesFilterValue xsi:nil="true"/>` (8 occurrences across ДО КОРП
    // 3.0.21.3 and ERP УХ 3.2.12.6), and `{"B",1}` the one it spells
    // `xsi:type="xs:boolean">true` (3 occurrences on ERP УХ). Neither carries
    // a payload shaped like the string or design-time-ref members.
    let undefined = decode(&collection(&item(
        "4",
        DOCUMENT_CHARACTERISTIC_TYPE_UUID,
        r#"{"U"}"#,
    )))
    .unwrap();
    assert_eq!(
        undefined.items()[0].types().types_filter_value(),
        &CharacteristicFilterValue::Undefined
    );
    let boolean = decode(&collection(&item(
        "4",
        DOCUMENT_CHARACTERISTIC_TYPE_UUID,
        r#"{"B",1}"#,
    )))
    .unwrap();
    assert_eq!(
        boolean.items()[0].types().types_filter_value(),
        &CharacteristicFilterValue::Boolean(true)
    );
    for malformed in [r#"{"U",1}"#, r#"{"B"}"#, r#"{"B",2}"#, r#"{"B",1,1}"#] {
        let diagnostic = decode(&collection(&item(
            "4",
            DOCUMENT_CHARACTERISTIC_TYPE_UUID,
            malformed,
        )))
        .unwrap_err();
        assert_eq!(
            diagnostic.reason,
            CharacteristicsReason::UnsupportedFilterUnion,
            "accepted malformed filter {malformed:?}"
        );
    }
}

