/// Real Subsystem text captured from ERP UH 3.2.12.6's `Web_Service.cf`
/// (`WebСервисУХ`, uuid `4070bb4b-b2e4-408e-9157-42cc46291d02`): a Subsystem
/// stored under discriminator 21, the same code the register families use.
/// Confirms both the header-index-1 classification rule in
/// `metadata_source_for_object_fields` and that
/// `parse_subsystem_properties_from_text` accepts code 21 as well as the
/// more common 22.
#[test]
fn code21_subsystem_classifies_and_extracts_like_code22() {
    let uuid = "4070bb4b-b2e4-408e-9157-42cc46291d02";
    let text = "{1,\r\n\
{21,\r\n\
{2,\r\n\
{1,0,4070bb4b-b2e4-408e-9157-42cc46291d02},\"WebСервисУХ\",\r\n\
{1,\"ru\",\"Web сервис УХ\"},\"\",0,1,7f676314-716a-4d54-8335-a71a3857b21c,3,00000000-0000-0000-0000-000000000000},1,\r\n\
{0,0},0,\r\n\
{4,0,\r\n\
{0},\"\",-1,-1,1,0,\"\"},\r\n\
{0},\r\n\
{0,4,\r\n\
{\"#\",157fa490-4ce9-11d4-9415-008048da11f9,\r\n\
{1,776b91d8-2253-47db-8dd6-11b6c2b4df55}\r\n\
},\r\n\
{\"#\",157fa490-4ce9-11d4-9415-008048da11f9,\r\n\
{1,d75fc78d-6801-4a64-9cd6-d79047ca2b24}\r\n\
},\r\n\
{\"#\",157fa490-4ce9-11d4-9415-008048da11f9,\r\n\
{1,36e515e5-9db0-4a1c-9a68-1df7625bdfaa}\r\n\
},\r\n\
{\"#\",157fa490-4ce9-11d4-9415-008048da11f9,\r\n\
{1,300c8045-655d-41da-bf92-d3de432334e1}\r\n\
}\r\n\
}\r\n\
},1,\r\n\
{37f2fa9a-b276-11d4-9435-004095e12fc7,0}\r\n\
}";
    let code = parse_metadata_object_code(text);
    assert_eq!(code, Some(21));
    let source = metadata_source_for_text(21, text, uuid);
    assert_eq!(source, Some(("Subsystem", "Subsystems")));

    let audit = metadata_text_row_audit_from_text(uuid, text.to_string());
    match audit {
        MetadataTextRowAudit::Extracted(row) => {
            assert_eq!(row.kind.as_deref(), Some("Subsystem"));
            assert_eq!(row.folder, Some("Subsystems"));
        }
        MetadataTextRowAudit::ExtractedWithWarning(row, miss) => {
            panic!(
                "expected clean extraction, got warning {miss:?} for row kind={:?} folder={:?}",
                row.kind, row.folder
            );
        }
        MetadataTextRowAudit::Miss(miss) => panic!("expected extraction, got miss {miss:?}"),
    }
}

/// Evidence: fixture `bot-predefined-picture`, two synthetic Bot objects
/// seeded on the Web_Service skeleton and round-tripped through platform
/// 8.3.27.2214. `БотА` has `Predefined=true` and no picture; `БотБ` has
/// `Predefined=false` and `Picture=StdPicture.Information` with
/// `LoadTransparent=true`. Combined with native UT 11.5.27.75's
/// `Bots/ОповещенияПользователейОСобытиях.xml` (`Predefined=false`, no
/// picture), the three round-trips gave the `Predefined` true/false and
/// `Picture` set/unset partition needed to extend
/// `parse_common_command_picture_value` to `Bot.Picture` -- see
/// `parse_bot_properties_from_text`.
fn assert_platform_proven_bot_predefined_and_picture(
    bot_uuid: &str,
    bot_text: &str,
    native_xml: &[u8],
    expected_predefined: bool,
    expected_picture_ref: Option<&str>,
) {
    let properties = parse_bot_properties_from_text(bot_text, bot_uuid, &BTreeMap::new())
        .expect("platform-proven Bot properties must decode");
    assert_eq!(properties.predefined, expected_predefined);
    assert_eq!(properties.picture_ref.as_deref(), expected_picture_ref);

    let bot_blob = deflate_for_test(bot_text.as_bytes());
    let extracted = extract_metadata_source_xml_with_refs(
        &bot_blob,
        bot_uuid,
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        &BTreeMap::new(),
        InfobaseConfigSourceVersion::V2_20,
    )
    .expect("platform-proven Bot must decode");
    assert_eq!(
        extracted.xml.as_slice(),
        native_xml,
        "extracted Bot XML must remain byte-identical to the native export"
    );
}

/// Real MOXCEL body captured from ERP UH 3.2.12.6 (`Web_Service.cf` and
/// `MDM_Management.cf` carry the identical body), data processor
/// `УниверсальнаяОтчетностьПоРегистрамУХ`, template `ОтчетПоПроводкам`.
///
/// Its line table has five entries and cites all five (full coverage), so
/// `compact_moxel_line_table`'s coverage check alone would keep it in stored
/// order: `[None/1, Solid/1, Solid/2, Dotted/1, ThinDashed/1]`. But the
/// platform publishes `[None/1, Solid/2, Solid/1, ThinDashed/1, Dotted/1]` -
/// confirmed against native ERP UH `Web_Service`/`MDM_Management` output
/// (both went from the single differing file on `ws` to 29/29). The
/// discriminator: this table's first *stored* entry is also the first entry
/// any format *cites* (citation order starts `[0, ...]`), unlike the SSL
/// demo and 1С:УТ full-coverage tables documented on
/// `compact_moxel_line_table` (their citation order starts with a raw index
/// other than 0, and reordering them breaks a byte-exact match) - see
/// `docs/evidence/mxl-line-table-order-lead.md`.
#[test]
fn full_coverage_line_table_reorders_when_first_entry_is_first_cited() {
    let text = include_str!("../../tests/fixtures/moxel_transaction_report_line_order_raw.txt");
    let spreadsheet =
        parse_moxel_spreadsheet_text(text, &BTreeMap::new()).expect("parse spreadsheet body");
    let observed: Vec<(&str, usize)> = spreadsheet
        .lines
        .iter()
        .map(|line| (line.style, line.width))
        .collect();
    assert_eq!(
        observed,
        vec![
            ("None", 1),
            ("Solid", 2),
            ("Solid", 1),
            ("ThinDashed", 1),
            ("Dotted", 1),
        ],
        "a fully-covered line table must still reorder by citation when its \
         own first stored entry is the first entry any format cites"
    );
}

